// -------------------------------------------------------------------------------------------
// the declaration

/// [definition] **A refinement as declared** (module header): the receiving ring `R`, the words
/// `K`, each word's full ticks `w`, the stations `m` and the termination class, with the receiver's
/// grain `L_R` read from the ring's declared receiver.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Refinement {
    ring: usize,
    words: usize,
    span: usize,
    stations: usize,
    termination: usize,
    grain: u64,
}

impl Refinement {
    /// **Declare a refinement** on a field: refused unless the ring has a declared receiver (its
    /// receiving map `R` and grain), `K, w, m ≥ 1`, the stations lie within one turn of the
    /// receiving ring (`m ≤ d_R`) and the termination class is a class of the exterior chart.
    pub fn declare(
        field: &Field,
        ring: usize,
        words: usize,
        span: usize,
        stations: usize,
        termination: usize,
    ) -> Result<Self, HnnError> {
        let receiver = field
            .receivers()
            .iter()
            .find(|receiver| receiver.ring == ring)
            .ok_or(HnnError::MissingReceivingMap { ring })?;
        if words == 0 || span == 0 || stations == 0 {
            return Err(HnnError::NonpositiveDeclaration);
        }
        let period = field.ring(ring).period();
        if stations as u64 > period {
            return Err(HnnError::Shape {
                what: "the section's stations within one turn of the receiving ring",
                expected: period as usize,
                found: stations,
            });
        }
        if termination >= field.alphabet() {
            return Err(HnnError::CellOutside {
                code: termination,
                alphabet: field.alphabet(),
            });
        }
        if !receiver.tolerance.is_positive() {
            return Err(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            });
        }
        let grain = receiver
            .tolerance
            .recip()
            .ceil()
            .to_integer()
            .to_u64()
            .ok_or(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            })?;
        Ok(Self {
            ring,
            words,
            span,
            stations,
            termination,
            grain,
        })
    }

    /// `R`.
    pub fn ring(&self) -> usize {
        self.ring
    }

    /// `K`.
    pub fn words(&self) -> usize {
        self.words
    }

    /// `w`.
    pub fn span(&self) -> usize {
        self.span
    }

    /// `m`.
    pub fn stations(&self) -> usize {
        self.stations
    }

    /// The termination class.
    pub fn termination(&self) -> usize {
        self.termination
    }

    /// `L_R`.
    pub fn grain(&self) -> u64 {
        self.grain
    }
}

// -------------------------------------------------------------------------------------------
// the release

/// [definition] **A section's release** (`section_release`): the decision, the width over the
/// section's fibre, each station's top class, the plural stations, the emitted classes (the
/// released section up to its first termination; empty unless released) and the first station at
/// the termination class.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SectionRelease {
    pub decision: ReleaseReturn,
    pub width: Rat,
    pub classes: Vec<usize>,
    pub plural: Vec<usize>,
    pub emitted: Vec<usize>,
    pub terminated: Option<usize>,
}

impl SectionRelease {
    /// Whether the section was released at width zero.
    pub fn released(&self) -> bool {
        matches!(self.decision, ReleaseReturn::Released { .. })
    }
}

/// **A section's release from its stations' classes and its plural stations** ([`bank_release`]):
/// width zero exactly when no station is plural, the discrete metric's one otherwise,
/// attained at the first plural station, decided at tolerance zero by the holding rule through
/// `receiver::release`; the released classes read up to the first termination.
fn section_release(
    declared: &Refinement,
    classes: Vec<usize>,
    plural: Vec<usize>,
) -> Result<SectionRelease, HnnError> {
    let (diameter, attaining) = match plural.first() {
        Some(&station) => (
            Rat::one(),
            WidthWitness::Coordinate {
                coordinate: station,
            },
        ),
        None => (Rat::zero(), WidthWitness::Point),
    };
    let width = ReceiverWidth::declared(
        format!("the section on receiving ring {}", declared.ring),
        "every station's top class at the grain, over the grain fibre of its logits",
        DiameterNorm::Supremum,
        diameter,
        attaining,
        classes.len().max(1),
    )?;
    let options = LawfulOptions::assemble(&width, Rat::zero(), None, false)?;
    let rule = DecisionRule::new(
        "the section's joint commit at tolerance zero",
        WithinTolerance::Release,
        BeyondTolerance::Hold,
    );
    let decision = release(&rule, &options)?;
    let terminated = classes
        .iter()
        .position(|&class| class == declared.termination);
    let emitted = match &decision {
        ReleaseReturn::Released { .. } => classes[..terminated.unwrap_or(classes.len())].to_vec(),
        _ => Vec::new(),
    };
    Ok(SectionRelease {
        decision,
        width: width.diameter().clone(),
        classes,
        plural,
        emitted,
        terminated,
    })
}

/// [definition; agent-inferred, U6's order repair] **The partition a training refinement compares**
/// (module header): the corruption chart of absorbing (masked) diffusion read on the stations. The
/// number `v` of locked stations is drawn uniformly from `0 … m − 1`, then `v` stations uniformly
/// (a partial Fisher–Yates draw); the rest are compared. Every partition a generation passes through
/// (nothing locked, then more) is one this law draws with positive mass, and at least one station is
/// always compared. `true` marks a locked (placed, uncompared) station.
pub fn mask(draw: &mut Draw, stations: usize) -> Vec<bool> {
    let mut order: Vec<usize> = (0..stations).collect();
    let locked = draw.below(stations.max(1));
    for i in 0..locked {
        let j = i + draw.below(stations - i);
        order.swap(i, j);
    }
    let mut visible = vec![false; stations];
    for &station in &order[..locked] {
        visible[station] = true;
    }
    visible
}

// -------------------------------------------------------------------------------------------
// generation by the receiving bank

/// [definition; agent-inferred, September 29] **A section generated by the receiving bank**
/// ([`generate_by_bank`]): its release, the refinements it took, the stations each locked, the turn
/// readings made, and at every lock the bank's certificate (the members certified at the locked
/// reading's growth, and the executed turn's ticks whose balance closed, of those run), with each
/// lock's station, class, growth and runner-up growth; and the lock whose Floquet certificate was
/// refused, if one was, where the release stopped and held (September 30: a refused certificate
/// refuses the lock, never a tally). Where the material holds pair contacts closed (their distances
/// in `contacts`; [`BankPlacement::contacts`]), each decision's enclosures are the candidates' gains
/// over their own columns read alone ([`gain`], [`BankPlacement::pair_storage`]), not their growths.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BankGeneration {
    pub release: SectionRelease,
    pub refinements: usize,
    pub locks: Vec<Vec<usize>>,
    pub readings: usize,
    pub certified: usize,
    pub members: usize,
    pub ticks_closed: usize,
    pub ticks: usize,
    pub decisions: Vec<(usize, usize, Growth, Growth)>,
    pub uncertified: Option<(usize, usize)>,
    pub contacts: Vec<usize>,
}

/// [definition; agent-inferred, October 5; the
/// [joint gain's record](../../../../research/records/2026-10-05_THE_PAIR_GAIN_IS_THE_JOINED_BANKS_LOG_DETERMINANT.md)
/// §3, revising lane C's least member] **A candidate's gain on equal material, read by the joined
/// bank**: the bank's relative transport from the candidate's column alone to its pair storage
/// ([`BankPlacement::pair_storage`]), read by its members together, its determinant on their lines,
///
/// ```text
/// Γ(j, x) = ∏_m g_m(z_pair) / g_m(z_alone),   log Γ = Σ_m (λ_m(z_pair) − λ_m(z_alone)),   λ_m = log g_m
/// enclosed exactly: [∏_m L_pair,m / U_alone,m,  ∏_m U_pair,m / L_alone,m]
/// ```
///
/// with `g_m` member `m`'s growth over the turn (its Floquet multiplier's modulus, enclosed by
/// [`ReceivingBank::read_turn`]). Why the determinant ([proved-derived], the record §3): the bank's
/// joint monodromy is its members' block sum ([`ReceivingBank::read_turn`]), so the full work form
/// over the joint state, `TᵀG₁T − rG₀`, is the direct sum of the members' and no cross term is
/// dropped by reading them one by one; each member is recharted on its own (its metric is attained,
/// any positive multiple certifying alike), so a ratio of joint quadratic forms reads a weight
/// between members that no owner supplies, and its weight-free limit, the joint growth, is the
/// largest member's alone; the ratio's additive chart (`ℓ = log R`, the loss law) on the direct sum
/// `R = ⊕_m R_m` is `log det R = Σ_m log det R_m`, the one joint reading in which a member whose two
/// storages turn alike (neutral, `g_m(z_pair) = g_m(z_alone)`) does not move the comparison. The
/// least member is not that reading: it is one member's, and a neutral member caps it at one. On
/// the alternation (`f = id`) every column is `(1 + P^δ) B e_x`, so on the members where `P^δ`
/// half-turns the contact's line every candidate's two storages vanish in the first-order chart and
/// the member is neutral for every class, and the least member decided on what remained past first
/// order (the regressions' record §8). On order-2 the antecedent's copy is anti-aligned with its
/// partner on those members and pays there what it gains on the others; the fit gains on every
/// member. No weight is set between the members or the two storages. Refused, typed, on a reading
/// alone whose lower end is not positive, or on two readings of different banks.
pub fn gain(pair: &TurnReading, alone: &TurnReading) -> Result<Growth, HnnError> {
    if pair.members.is_empty() || pair.members.len() != alone.members.len() {
        return Err(HnnError::NonpositiveDeclaration);
    }
    let mut joined = Growth {
        lower: Rat::one(),
        upper: Rat::one(),
    };
    for (p, a) in pair.members.iter().zip(&alone.members) {
        if !a.lower.is_positive() {
            return Err(HnnError::NonpositiveDeclaration);
        }
        joined.lower *= &p.lower / &a.upper;
        joined.upper *= &p.upper / &a.lower;
    }
    Ok(joined)
}

/// [definition; agent-inferred, September 30] **One refinement of the bank's lock iteration**
/// ([`bank_release`]): the section placed before it, every open candidate `(station, class)` in
/// station-major order with its reading, each open station's top class, the eligible stations
/// (the top's flip and lock both certified) with their gaps, and the stations it locked.
#[derive(Clone, Debug)]
pub struct BankRefinement<R> {
    pub placed: Vec<Option<usize>>,
    pub open: Vec<(usize, usize)>,
    pub read: Vec<R>,
    pub tops: Vec<(usize, usize)>,
    pub eligible: Vec<(usize, usize, Rat)>,
    pub locked: Vec<usize>,
}

/// [definition; agent-inferred, September 30] **A candidate's reading as the lock iteration reads
/// it**: its joint growth enclosure.
pub trait JointGrowth {
    /// The turn's reading.
    fn reading(&self) -> &TurnReading;
    /// Its joint growth enclosure.
    fn joint(&self) -> &Growth {
        &self.reading().joint
    }
}

impl JointGrowth for TurnReading {
    fn reading(&self) -> &TurnReading {
        self
    }
}

impl JointGrowth for TurnCovector {
    fn reading(&self) -> &TurnReading {
        &self.reading
    }
}

/// [definition; agent-inferred, September 29] **Generate a section by the receiving bank's locks**
/// (module header, "The bank reads the superposed passage"). The request's placement is fixed and
/// nothing is locked. In each refinement, for every unlocked station and every class of the
/// exterior chart, the receiving ring's storage is the request's placement with the locked data
/// and that candidate placed at their stations' residues, each datum at its transported weight
/// read from the candidate's station ([`BankPlacement::storage`]; the passage's one population at
/// modulus one), the other unlocked stations unplaced; the bank reads its turn
/// ([`ReceivingBank::read_turn`]). A station's reading is the lock's flip: its top candidate's joint
/// growth exceeds every other candidate's exactly ([`Growth::exceeds`], `θ = a/(a + K) > ½`) and the
/// bank locks there ([`Growth::is_locked`]); its gap is the top's `lower` less the largest other
/// `upper`, its upper end the top's `upper` less the largest other `lower`. Every station whose upper end
/// meets the largest positive gap locks (the readings do not order it below), its reading certified
/// ([`ReceivingBank::certify_turn`]); a locked datum is placed for the next refinement. It stops when
/// every station is locked, released at width zero through `receiver::release` (`section_release`),
/// or when no unlocked station has a positive gap, held with them plural, or when a lock's
/// Floquet certificate is refused, held with the open stations plural (the refusal named). Nothing
/// is deposited: the constitution is read at its cut (`E`, placed through the source port), and the
/// bank's members are declared. The readings of one refinement are co-present regions: shared
/// immutable input, one output each, so they run on the host's cores.
///
/// [definition; agent-inferred, October 5] **Where the material holds a pair contact closed**
/// ([`closed_pairs`], read at the placement from the material and the field's declared port), each
/// candidate's storage is its pair storage and its decision enclosure its gain on equal material
/// (module header, "The release reads the located pair on equal material";
/// [`BankPlacement::pair_storage`]); only the stations a closed contact joins to a placed crossing
/// are read in a refinement, and the bank locks on the pair storage's joint growth.
#[allow(clippy::too_many_arguments)]
pub fn generate_by_bank(
    field: &Field,
    constitution: &impl FieldMaterial,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    bank: &ReceivingBank,
    grain: u32,
) -> Result<BankGeneration, HnnError> {
    let ring = declared.ring;
    if !field.is_source(ring) {
        return Err(HnnError::MissingSourcePort { ring });
    }
    let placement = BankPlacement::of(field, constitution, current, moment, declared)?;
    let (generation, _) = bank_release(
        &placement,
        declared,
        field.alphabet(),
        bank,
        grain,
        |amplitudes| bank.read_turn(amplitudes, grain),
        false,
    )?;
    Ok(generation)
}

/// [definition; agent-inferred, September 30] **The bank's lock iteration, its one owner**
/// ([`generate_by_bank`]'s law; the retired comparison read it with each candidate's covector,
/// S2): every refinement reads every open candidate by `read`, decides each
/// open station's lock's flip and gap, locks together the stations not certified below the largest
/// positive gap,
/// certifies each lock's reading, and stops at the whole section, at a plural refinement, or at a
/// refused certificate. With `keep`, each refinement's readings are returned.
pub fn bank_release<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    bank_release_ordered(placement, declared, alphabet, bank, grain, read, keep, LockOrder::Gap)
}

/// [definition; agent-inferred, loop 1c's
/// [pin](../../../../research/records/2026-10-01_LOOP_1C_PERSISTENCE_REPRESENTATION_AND_REACH_PINNED_BEFORE_ITS_RUNS.md)
/// §2.4] **Which eligible stations a refinement locks.** The release's law is [`LockOrder::Gap`]:
/// the stations whose gap the readings do not certify below the largest, together (the field's
/// own order). The other two are
/// diagnostics of the release's order, never a law: among the same eligible stations (each top's
/// flip and lock certified, its gap positive) a refinement locks the one of least station index
/// ([`LockOrder::Ascending`], the receiving ring's clock direction from the request's last tick) or
/// of greatest ([`LockOrder::Descending`]), one lock a refinement. Eligibility, the readings, the
/// certificates and the stopping rules are the release's own under every order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LockOrder {
    /// The release's law: the stations not certified below the largest positive gap lock together.
    Gap,
    /// A diagnostic: the eligible station of least index locks alone.
    Ascending,
    /// A diagnostic: the eligible station of greatest index locks alone.
    Descending,
}

/// [definition; agent-inferred, October 2; its consequences proved-derived, formal-checked] **The
/// stations the readings do not certify below the largest gap** ([`LockOrder::Gap`]): each eligible station's gap is enclosed by its certain
/// gap `L_top − max_(x≠top) U_x` and its upper end `U_top − max_(x≠top) L_x`; a station locks when its
/// upper end meets the largest certain gap. The station of the largest certain gap always locks, so a
/// refinement with an eligible station locks one (Lean
/// `HNN/ExecutedComparison.certifiedLock_largest`); the true largest gap always locks
/// (`leader_locks`); a station that locks alone has the strictly largest true gap
/// (`lone_lock_is_largest`), so no move makes a station certified below another lock alone before it
/// unless their true gaps cross (`certified_order_needs_crossing`). On exact readings it is the
/// largest gap with its ties (`certifiedLock_exact`). The comparison's order term reads the same
/// two ends (the retired `hnn::executed::OrderTerm` at `9078f103`; `order_solved_locks_no_wrong`).
pub(crate) fn uncertified_largest(gaps: &[(usize, usize, Rat)], gap_uppers: &[Rat]) -> Vec<usize> {
    let largest = gaps.iter().map(|(_, _, gap)| gap).max();
    match largest {
        Some(largest) => gaps
            .iter()
            .zip(gap_uppers)
            .filter(|(_, gap_upper)| *gap_upper >= largest)
            .map(|(&(station, _, _), _)| station)
            .collect(),
        None => Vec::new(),
    }
}

/// **The bank's lock iteration under a declared order** ([`bank_release`] at [`LockOrder::Gap`];
/// the other orders are diagnostics of the release's order, [`LockOrder`]).
#[allow(clippy::too_many_arguments)]
pub fn bank_release_ordered<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
    order: LockOrder,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    release_iteration(placement, declared, alphabet, bank, grain, read, keep, order, None)
}

/// [measured-diagnostic; agent-inferred, October 1; the
/// [forced release's record](../../../../research/records/2026-10-01_THE_FORCED_RELEASE.md)]
/// **The forced release**: the release's own lock iteration under its own law ([`LockOrder::Gap`]:
/// which stations lock, from their own readings), each lock placed at its declared target class
/// instead of its top. Its refinements are the contexts the release would read had every earlier
/// lock been right: a comparison read there covers every decision the release faces along the
/// right trajectory, so if every one is solved the section is whole, lock by lock. A placed target
/// is a reading context, not a commit: its Floquet certificate is not read. Never a release law.
#[allow(clippy::too_many_arguments)]
pub fn bank_release_forced<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    targets: &[usize],
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    release_iteration(placement, declared, alphabet, bank, grain, read, true, LockOrder::Gap, Some(targets))
}

/// The lock iteration ([`bank_release_ordered`], [`bank_release_forced`]).
#[allow(clippy::too_many_arguments)]
fn release_iteration<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
    order: LockOrder,
    forced: Option<&[usize]>,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    use rayon::prelude::*;
    let stations = declared.stations;
    let mut locked: Vec<Option<usize>> = vec![None; stations];
    let mut tops: Vec<usize> = vec![declared.termination; stations];
    let mut locks: Vec<Vec<usize>> = Vec::new();
    let mut plural: Vec<usize> = Vec::new();
    let mut decisions = Vec::new();
    let mut kept = Vec::new();
    let mut uncertified = None;
    let (mut refinements, mut readings, mut certified, mut members) = (0, 0, 0, 0);
    let (mut ticks_closed, mut ticks) = (0, 0);
    // The pair contacts the material holds closed: with any, every candidate reads its own pair
    // storage against its own column alone (`BankPlacement::pair_storage`).
    let joined = !placement.contacts().is_empty();
    while locked.iter().any(Option::is_none) {
        let placed = locked.clone();
        // Each candidate reads the span from its own station (the station-framed law), or, where
        // the material carries pair contacts, the crossings its contacts join to it.
        let storage = |station: usize, class: usize| -> Vec<Rat> {
            if joined {
                let (pair, _) = placement
                    .pair_storage(station, class, &placed)
                    .expect("a station joined to a placed crossing");
                return pair;
            }
            let mut cells = placed.clone();
            cells[station] = Some(class);
            placement.storage(station, &cells)
        };
        let open: Vec<(usize, usize)> = (0..stations)
            .filter(|&station| locked[station].is_none())
            .filter(|&station| !joined || placement.joins(station, &placed))
            .flat_map(|station| (0..alphabet).map(move |class| (station, class)))
            .collect();
        let both: Vec<(R, Option<R>)> = open
            .par_iter()
            .map(|&(station, class)| {
                if joined {
                    let (pair, alone) = placement
                        .pair_storage(station, class, &placed)
                        .expect("a station joined to a placed crossing");
                    Ok((read(&turn(&pair))?, Some(read(&turn(&alone))?)))
                } else {
                    Ok((read(&turn(&storage(station, class)))?, None))
                }
            })
            .collect::<Result<Vec<_>, HnnError>>()?;
        // Each candidate's decision enclosure: its joint growth, or, on equal material, its gain
        // over its own column read alone.
        let decided: Vec<Growth> = both
            .iter()
            .map(|(reading, alone)| match alone {
                Some(alone) => gain(reading.reading(), alone.reading()),
                None => Ok(reading.joint().clone()),
            })
            .collect::<Result<Vec<_>, HnnError>>()?;
        refinements += 1;
        readings += both.iter().map(|(_, alone)| 1 + usize::from(alone.is_some())).sum::<usize>();
        let read: Vec<R> = both.into_iter().map(|(reading, _)| reading).collect();
        // Each unlocked station's lock's flip: its top candidate and its gap's enclosure, the
        // certain gap `L_top − max U` (the gap read) and its upper end `U_top − max L`.
        let mut gaps: Vec<(usize, usize, Rat)> = Vec::new();
        let mut gap_uppers: Vec<Rat> = Vec::new();
        let mut station_tops = Vec::new();
        for (index, chunk) in decided.chunks(alphabet).enumerate() {
            let station = open[index * alphabet].0;
            let best = (0..alphabet)
                .max_by(|&a, &b| chunk[a].lower.cmp(&chunk[b].lower).then(b.cmp(&a)))
                .expect("a class");
            tops[station] = best;
            station_tops.push((station, best));
            let top = &chunk[best];
            let runner = (0..alphabet)
                .filter(|&class| class != best)
                .map(|class| chunk[class].upper.clone())
                .max();
            let flips = (0..alphabet)
                .filter(|&class| class != best)
                .all(|class| top.exceeds(&chunk[class]));
            // The bank locks on the candidate's own storage: its joint growth past one.
            if flips && read[index * alphabet + best].joint().is_locked() {
                let gap = match &runner {
                    Some(runner) => &top.lower - runner,
                    None => top.lower.clone(),
                };
                let floor = (0..alphabet)
                    .filter(|&class| class != best)
                    .map(|class| chunk[class].lower.clone())
                    .max();
                let gap_upper = match &floor {
                    Some(floor) => &top.upper - floor,
                    None => top.upper.clone(),
                };
                gaps.push((station, best, gap));
                gap_uppers.push(gap_upper);
            }
        }
        let now: Vec<usize> = match order {
            LockOrder::Gap => uncertified_largest(&gaps, &gap_uppers),
            LockOrder::Ascending => gaps.iter().map(|&(station, _, _)| station).min().into_iter().collect(),
            LockOrder::Descending => gaps.iter().map(|&(station, _, _)| station).max().into_iter().collect(),
        };
        let mut taken = Vec::new();
        for &station in &now {
            let class = forced.map_or(tops[station], |targets| targets[station]);
            let index = open
                .iter()
                .position(|&pair| pair == (station, class))
                .expect("a read candidate");
            let reading = decided[index].clone();
            let amplitudes = turn(&storage(station, class));
            let certificate = if forced.is_some() {
                Ok(None)
            } else {
                bank.certify_turn(&amplitudes, read[index].reading(), grain).map(Some)
            };
            match certificate {
                Ok(None) => {}
                Ok(Some(certificate)) => {
                    certified += certificate.certificates.len();
                    ticks_closed += certificate.closed;
                    ticks += certificate.ticks;
                }
                // A refused certificate refuses the lock and the release: with the reading's upper
                // end strictly outside every multiplier, the exact Stein solve of the exact
                // monodromy always certifies, so a refusal can only mean the reading itself is
                // wrong.
                Err(HnnError::UncertifiedFloquet { .. }) => {
                    uncertified = Some((station, class));
                    break;
                }
                Err(error) => return Err(error),
            }
            members += bank.pumps().len();
            let runner = (0..alphabet)
                .filter(|&other| other != class)
                .map(|other| decided[index - class + other].clone())
                .max_by(|a, b| a.upper.cmp(&b.upper))
                .expect("a runner-up");
            decisions.push((station, class, reading, runner));
            locked[station] = Some(class);
            taken.push(station);
        }
        let stop = now.is_empty() || uncertified.is_some();
        if stop {
            plural = (0..stations)
                .filter(|&station| locked[station].is_none())
                .collect();
            if let Some((station, _)) = uncertified {
                plural.retain(|&s| s != station);
                plural.insert(0, station);
            }
        }
        if keep {
            kept.push(BankRefinement {
                placed: placed.clone(),
                open,
                read,
                tops: station_tops,
                eligible: gaps,
                locked: taken.clone(),
            });
        }
        if !taken.is_empty() {
            locks.push(taken);
        }
        if stop {
            break;
        }
    }
    let classes: Vec<usize> = locked
        .iter()
        .zip(&tops)
        .map(|(lock, &top)| lock.unwrap_or(top))
        .collect();
    Ok((
        BankGeneration {
            release: section_release(declared, classes, plural)?,
            refinements,
            locks,
            readings,
            certified,
            members,
            ticks_closed,
            ticks,
            decisions,
            uncertified,
            contacts: placement.contacts().to_vec(),
        },
        kept,
    ))
}

/// [definition; agent-inferred, September 29; the passage law, September 30; the station-framed
/// law, September 30] **The receiving ring's storage under the passage, read from a station**
/// ([`generate_by_bank`]; module header, "The section continues the request's passage"): each
/// occupied phase's read of the request's raw counts `P^(λ−c) E M[c]` on the receiving ring, the
/// pair ports' normalized read, and, per station `j` and class `x`, the datum's image
/// `P^(λ − c_j) E e_x`, `c_j = τ + 1 + j` (mod `d`). A candidate at station `j` reads the span, the
/// request and the section's cells `S`, as one field, each datum weighed by its two-sided transport
/// distance from `j`:
///
/// ```text
/// z_j(S) = z_pairs + Σ_c w_j(c) P^(λ−c) E M[c] + Σ_(i∈S) w_j(i) P^(λ − c_i) E e_(x_i)
/// w_j(k) = chart(ρ^(r_j(k)) / (Σ_c n(c) ρ^(r_j(c)) + Σ_(i∈S) ρ^(r_j(i))))
/// r_j(c) = 1 + j + ((τ − c) mod d)   (a request phase),   r_j(i) = |i − j|   (a station)
/// ```
///
/// with `ρ` the navigator's transport modulus: at `ρ = 1` every datum weighs `ν̂(n + |S|)`, in
/// every frame. **Why two-sided** [agent-inferred, the
/// [re-entry diagnosis](../../../../research/records/2026-09-30_THE_RE_ENTRY_DIAGNOSED_A_LATER_LOCK_TAKES_THE_SPANS_MASS_AND_QUENCHES_THE_EARLIER_STATIONS.md)
/// §6]: the section is a joint field, refined whole, not a stream read in time order, so the
/// reading at station `j` is the dissipative tube's stationary response to each datum, which
/// falls by `ρ` a tick in both directions of the tube (the tube's pairing reading, `ρ^|Δ|`, the
/// stationary covariance of a transport of modulus `ρ` a tick); the one-way dilation
/// `ρ^(τ_end − τ_k)` read at the span's end grows backward from `j`, so a lock `r` ticks after `j`
/// weighed `ρ^(−r)` times `j`'s own candidate and took the span's mass (the diagnosis measured up to
/// `[205/256, 103/128]` of it from station 0). Read from `j`:
/// - **on data no later than `j` it is the one-way law exactly** (the common factor `ρ^(τ_end − τ_j)`
///   cancels in the normalization; Lean `HNN/IndexedOpen.framed_weight_one_sided`), so the open
///   section, which holds only the request and the candidate, reads as before, and so does a
///   station read after every lock;
/// - **a datum `r ≥ 1` ticks from `j` weighs at most `ρ^r`** of `j`'s span, the candidate's own
///   datum weighing one before the normalization (`framed_weight_le_pow`), so a far lock no longer
///   quenches an earlier station;
/// - **every datum enters**, none is dropped by its distance or the span's length, and each
///   station's normalization is its own systolic reduction over the same carried powers `ρ^r`;
/// - **every modality reads it the same way**: the law reads only the distance between two ticks
///   of the ring's clock; a text cell, an image pixel at its scan tick (its row neighbours at
///   distance one on either side, the pixels one row away at the row's width), an acoustic sample
///   at its sample tick, a motor screw at its step.
///
/// The request's reads are kept once and every candidate is read without re-encoding the request;
/// held to the explicit two-sided formula exactly by the owner's tests, and to the continued
/// passage's open ([`SourceMoment::continued`], read at the span's last datum) exactly when no
/// placed datum lies after the station read. With nothing placed it is the request's own open.
#[derive(Clone, Debug)]
pub struct BankPlacement {
    /// Each occupied request phase: its lag `(τ − c) mod d` behind the request's last tick, its
    /// count and its read.
    reads: Vec<(u64, u64, Vec<Rat>)>,
    pairs: Vec<Rat>,
    images: Vec<Vec<Vec<Rat>>>,
    chart: PopulationChart,
    modulus: Rat,
    stations: u64,
    /// `ρ^r` for every distance `r < d + m`.
    powers: Vec<Rat>,
    population: u64,
    /// The receiving ring's period `d`.
    period: u64,
    /// The distances at which the source port holds a pair contact closed ([`closed_pairs`]).
    contacts: Vec<usize>,
}

impl BankPlacement {
    /// The request's reads and every station's class images on the receiving ring. Refused, at a
    /// transport below modulus one, when the request and its declared stations span more than one
    /// turn ([`HnnError::AliasedAges`]).
    pub fn of(
        field: &Field,
        constitution: &impl FieldMaterial,
        current: &Current,
        moment: &SourceMoment,
        declared: &Refinement,
    ) -> Result<Self, HnnError> {
        let ring = declared.ring;
        let port = constitution
            .source_port(ring)
            .ok_or(HnnError::MissingSourcePort { ring })?;
        let geometry = field.ring(ring);
        let period = geometry.period();
        let modulus = constitution.transport(ring);
        let stations = declared.stations as u64;
        // The span's check: the moment read over its declared stations (every station placed).
        let full = moment.continued(field, current, ring, &vec![Some(0); declared.stations])?;
        full.phase_weights(field, ring, &modulus)?;
        let (raw, pairs) = moment.open_parts(field, constitution, current, ring)?;
        let phase = current.phase(field, ring)?;
        let reads = raw
            .into_iter()
            .map(|(c, read)| -> Result<(u64, u64, Vec<Rat>), HnnError> {
                let c = c as u64;
                let lag = (phase + period - c) % period;
                let count: u64 = moment.phase_counts(ring, c as usize)?.iter().sum();
                Ok((lag, count, read))
            })
            .collect::<Result<Vec<_>, _>>()?;
        let lift = current.lift()[ring].clone();
        let columns: Vec<Vec<Rat>> = (0..field.alphabet())
            .map(|class| {
                (0..port.rows())
                    .map(|row| port.get(row, class).cloned())
                    .collect::<Result<Vec<_>, _>>()
            })
            .collect::<Result<Vec<_>, _>>()?;
        let images = (0..declared.stations)
            .map(|station| {
                let residue = (phase + 1 + station as u64) % period;
                let rotation = &lift - BigInt::from(residue);
                columns
                    .iter()
                    .map(|column| geometry.rotate(column, &rotation))
                    .collect()
            })
            .collect();
        let mut powers = Vec::with_capacity((period + stations) as usize);
        let mut power = Rat::one();
        for _ in 0..period + stations {
            powers.push(power.clone());
            power *= &modulus;
        }
        Ok(Self {
            reads,
            pairs,
            images,
            chart: PopulationChart::of(field),
            modulus,
            stations,
            powers,
            population: moment.population(ring)?,
            period,
            contacts: closed_pairs(field, constitution, ring)?,
        })
    }

    /// The navigator's transport modulus the placement weighs at.
    pub fn modulus(&self) -> &Rat {
        &self.modulus
    }

    /// **The pair contacts the release reads**: the distances `δ` at which the source port holds a
    /// pair contact closed ([`closed_pairs`]), read from the material at the placement; empty on a
    /// port that carries no located pair.
    pub fn contacts(&self) -> &[usize] {
        &self.contacts
    }

    /// Whether a residue lies `δ` ticks from another on the receiving ring, either way round, for
    /// a closed contact's `δ`: `r ≡ ±δ (mod d)`.
    fn contact_distance(&self, distance: u64) -> bool {
        let r = distance % self.period;
        self.contacts.iter().any(|&delta| {
            let delta = delta as u64 % self.period;
            r == delta || r == (self.period - delta) % self.period
        })
    }

    /// **The crossings a closed pair contact joins to station `j`**: every request phase and every
    /// placed station whose residue lies `δ` ticks from `c_j`, either way round, for each closed
    /// contact's `δ`; each with its count and its read (a request phase's raw counts read, a
    /// station's class image).
    fn partners<'a>(&'a self, station: usize, cells: &[Option<usize>]) -> Vec<(u64, &'a Vec<Rat>)> {
        let mut partners: Vec<(u64, &Vec<Rat>)> = self
            .reads
            .iter()
            .filter(|(lag, _, _)| self.contact_distance(Self::request_distance(station, *lag)))
            .map(|(_, count, read)| (*count, read))
            .collect();
        for (placed, cell) in cells.iter().enumerate() {
            if let Some(class) = cell
                && placed != station
                && self.contact_distance(Self::station_distance(station, placed))
            {
                partners.push((1, &self.images[placed][*class]));
            }
        }
        partners
    }

    /// Whether a closed pair contact joins station `j` to a placed crossing ([`BankPlacement::partners`]).
    pub fn joins(&self, station: usize, cells: &[Option<usize>]) -> bool {
        !self.partners(station, cells).is_empty()
    }

    /// [definition; agent-inferred, October 5; lane C's
    /// [record](../../../../research/records/2026-10-05_THE_RELEASE_READS_THE_LOCATED_PAIR_ON_EQUAL_MATERIAL.md)]
    /// **A candidate's pair storage and its own column alone, on equal material.** The candidate
    /// `x` at station `j` and the crossings the source port's closed pair contacts join to it
    /// ([`BankPlacement::partners`]: residues `c_j ± δ`, from the request or from the section's
    /// locked stations), as one population at the contact's own weight. The contact's channel is the
    /// turn the deposit carried, `U = P^δ` (`(E − B) T = P^δ B`): a rotation of the ring, a mode of
    /// modulus one, stored and carried without loss. So the partner is read through it without the
    /// tube's contraction `ρ^δ`, which every datum of the span takes alike (one scalar modulus a
    /// ring) and which made the nearest lock outweigh the pair; no weight is chosen, and none is cut
    /// off,
    ///
    /// ```text
    /// z_pair(j, x) = ν̂(N) ( P^(λ−c_j) E e_x + Σ_(p joined to j) P^(λ−c_p) E M[p] ),   N = 1 + Σ_p n(p)
    /// z_alone(j, x) = ν̂(N) P^(λ−c_j) E e_x
    /// ```
    ///
    /// With `(E − B) e_x = P^δ B e_y` (the deposit's consumer, `hnn::executed::pair_deposit`), a
    /// candidate that fits the contact carries, at its antecedent's placement, the antecedent's
    /// prior image a second time, `P^(λ−c_j) (E − B) e_x = P^(λ−c_(j−δ)) B e_y`: the two add
    /// coherently. The release compares the bank's reading of `z_pair` against the same bank's
    /// reading of `z_alone` (the gain), so a class's own column, whatever its resonance power,
    /// enters both and only what the contact adds decides. `None` when no closed contact joins `j`
    /// to a placed crossing: the station waits for its antecedent (or its consequence) to lock.
    /// Every modality reads it the same way: a contact joins two ticks of the ring's clock.
    pub fn pair_storage(
        &self,
        station: usize,
        class: usize,
        cells: &[Option<usize>],
    ) -> Option<(Vec<Rat>, Vec<Rat>)> {
        let partners = self.partners(station, cells);
        if partners.is_empty() {
            return None;
        }
        let population = 1 + partners.iter().map(|(count, _)| count).sum::<u64>();
        let nu = self.chart.value(population);
        let own = &self.images[station][class];
        let alone: Vec<Rat> = own.iter().map(|x| x * &nu).collect();
        let mut pair = own.clone();
        for (_, read) in &partners {
            for (value, add) in pair.iter_mut().zip(read.iter()) {
                *value += add;
            }
        }
        Some((pair.iter().map(|x| x * &nu).collect(), alone))
    }

    /// The declared stations `m`.
    pub fn stations(&self) -> usize {
        self.stations as usize
    }

    /// **A request phase's distance from the station read**: `1 + j + lag`, the ticks from the
    /// phase's last crossing to station `j`'s.
    fn request_distance(station: usize, lag: u64) -> u64 {
        1 + station as u64 + lag
    }

    /// **A placed station's distance from the station read**: `|i − j|`, on either side.
    fn station_distance(station: usize, placed: usize) -> u64 {
        station.abs_diff(placed) as u64
    }

    /// Every datum of the span read from `station`: its distance, its count and its read (the
    /// request's phases, then the placed stations in order).
    fn data<'a>(
        &'a self,
        station: usize,
        cells: &[Option<usize>],
    ) -> Vec<(u64, Rat, &'a Vec<Rat>)> {
        assert!(station < self.stations(), "the station read is a declared station");
        let mut data: Vec<(u64, Rat, &Vec<Rat>)> = self
            .reads
            .iter()
            .map(|(lag, count, read)| {
                (
                    Self::request_distance(station, *lag),
                    Rat::from_integer(BigInt::from(*count)),
                    read,
                )
            })
            .collect();
        for (placed, cell) in cells.iter().enumerate() {
            if let Some(class) = cell {
                data.push((
                    Self::station_distance(station, placed),
                    Rat::one(),
                    &self.images[placed][*class],
                ));
            }
        }
        data
    }

    /// The span's transported mass read from `station`,
    /// `Σ_c n(c) ρ^(r_j(c)) + Σ_(i∈S) ρ^(|i − j|)`, exactly.
    fn mass(&self, station: usize, cells: &[Option<usize>]) -> Rat {
        self.data(station, cells)
            .iter()
            .map(|(distance, count, _)| &self.powers[*distance as usize] * count)
            .sum()
    }

    /// **The passage's weights read from a station**: each request phase's and each placed
    /// station's `w_j`, on the population chart; at `ρ = 1` all `ν̂(n + |S|)`, in every frame.
    #[allow(clippy::type_complexity)]
    pub fn weights(&self, station: usize, cells: &[Option<usize>]) -> (Vec<Rat>, Vec<Option<Rat>>) {
        self.weights_over(station, cells, cells)
    }

    /// The weights of the data `cells` read from `station`, normalized over the span `mass` places
    /// (the request's phases and the stations `mass` places; only which stations are placed counts,
    /// never their classes). At `mass = cells` it is [`BankPlacement::weights`].
    #[allow(clippy::type_complexity)]
    fn weights_over(
        &self,
        station: usize,
        cells: &[Option<usize>],
        mass: &[Option<usize>],
    ) -> (Vec<Rat>, Vec<Option<Rat>>) {
        assert!(station < self.stations(), "the station read is a declared station");
        if self.modulus.is_one() {
            let placed = mass.iter().filter(|cell| cell.is_some()).count() as u64;
            let nu = self.chart.value(self.population + placed);
            return (
                vec![nu.clone(); self.reads.len()],
                cells.iter().map(|cell| cell.map(|_| nu.clone())).collect(),
            );
        }
        let mass = self.mass(station, mass);
        let weigh = |distance: u64| self.chart.chart(&(&self.powers[distance as usize] / &mass));
        (
            self.reads
                .iter()
                .map(|(lag, _, _)| weigh(Self::request_distance(station, *lag)))
                .collect(),
            cells
                .iter()
                .enumerate()
                .map(|(placed, cell)| cell.map(|_| weigh(Self::station_distance(station, placed))))
                .collect(),
        )
    }

    /// **The receiving ring's storage read from a station** with the section's cells placed (a
    /// station's class, or unplaced): the pair ports' read plus every datum of the passage at its
    /// transported weight from `station`.
    pub fn storage(&self, station: usize, cells: &[Option<usize>]) -> Vec<Rat> {
        self.storage_over(station, cells, cells)
    }

    /// [measured-diagnostic; agent-inferred, loop 1c's
    /// [pin](../../../../research/records/2026-10-01_LOOP_1C_PERSISTENCE_REPRESENTATION_AND_REACH_PINNED_BEFORE_ITS_RUNS.md)
    /// §2.3; a diagnostic, never a law] **The storage read from a station with its normalization
    /// taken over another span**: the data `cells` enter (the request's phases and the stations
    /// `cells` places, the candidate's own among them), each at its transported weight from `station`
    /// over the mass of the span `mass` places, `chart(ρ^(r(k)) / M_j(mass))`. At `mass = cells` it is
    /// [`BankPlacement::storage`] exactly. A later lock `k` landing on a section `S` read from `j`
    /// splits into two parts (Lean `HNN/IndexedOpen.transported_weight_insert`): **the
    /// normalization**, every earlier datum's weight scaled by `M_j(S)/M_j(S ∪ k)` (the span's mass
    /// taken by `k`; `storage_over(j, S, S ∪ k)`), and **the entry**, `k`'s own image at its weight
    /// (`storage_over(j, S ∪ k, S)` adds it over the earlier mass). On the chart, with one mass the
    /// common data read one weight, so `storage(j, S ∪ k) − storage_over(j, S, S ∪ k)` and
    /// `storage_over(j, S ∪ k, S) − storage(j, S)` are each exactly `k`'s entry (the owner's test).
    pub fn storage_over(
        &self,
        station: usize,
        cells: &[Option<usize>],
        mass: &[Option<usize>],
    ) -> Vec<Rat> {
        let (request, section) = self.weights_over(station, cells, mass);
        let mut storage = self.pairs.clone();
        for ((_, _, read), weight) in self.reads.iter().zip(&request) {
            for (value, add) in storage.iter_mut().zip(read) {
                *value += add * weight;
            }
        }
        for (placed, (cell, weight)) in cells.iter().zip(&section).enumerate() {
            if let (Some(class), Some(weight)) = (cell, weight) {
                for (value, add) in storage.iter_mut().zip(&self.images[placed][*class]) {
                    *value += add * weight;
                }
            }
        }
        storage
    }

    /// The storage's derivative in the modulus rebuilt from each datum's reach slope,
    /// `Σ_k (ρ^(r_k)/M) s_k read_k` ([`BankPlacement::reach_slopes`] against
    /// [`BankPlacement::modulus_derivative`], the owner's test).
    #[cfg(test)]
    pub(crate) fn reach_derivative(&self, station: usize, cells: &[Option<usize>]) -> Vec<Rat> {
        let mass = self.mass(station, cells);
        let (request, section) = self.reach_slopes(station, cells);
        let mut derivative = vec![Rat::zero(); self.pairs.len()];
        let mut add = |distance: u64, slope: &Rat, read: &[Rat]| {
            let factor = &self.powers[distance as usize] / &mass * slope;
            for (value, x) in derivative.iter_mut().zip(read) {
                *value += x * &factor;
            }
        };
        for ((lag, _, read), slope) in self.reads.iter().zip(&request) {
            add(Self::request_distance(station, *lag), slope, read);
        }
        for (placed, (cell, slope)) in cells.iter().zip(&section).enumerate() {
            if let (Some(class), Some(slope)) = (cell, slope) {
                add(Self::station_distance(station, placed), slope, &self.images[placed][*class]);
            }
        }
        derivative
    }

    /// The storage read from a station at the exact transported weights at a modulus (no chart):
    /// the test's reference for [`BankPlacement::modulus_derivative`].
    #[cfg(test)]
    pub(crate) fn exact_storage(
        &self,
        station: usize,
        cells: &[Option<usize>],
        modulus: &Rat,
    ) -> Vec<Rat> {
        let power = |distance: u64| crate::hnn::moment::modulus_power(modulus, distance);
        let data = self.data(station, cells);
        let mass: Rat = data.iter().map(|(distance, count, _)| power(*distance) * count).sum();
        let mut storage = self.pairs.clone();
        for (distance, _, read) in data {
            let weight = power(distance) / &mass;
            for (value, add) in storage.iter_mut().zip(read) {
                *value += add * &weight;
            }
        }
        storage
    }

    /// [definition; agent-inferred, September 30] **The storage's derivative in the transport
    /// modulus**, read from a station, at the exact weights `w_k = ρ^(r_k)/mass`:
    /// `∂w_k/∂ρ = w_k (r_k − r̄)/ρ`, `r_k` the datum's distance from the station read and `r̄` the
    /// span's weighted mean distance, so `∂z/∂ρ = Σ_k ∂w_k/∂ρ · (datum k's read)`; the modulus's
    /// covector paired with it in the retired descent move (`hnn::executed` at `9078f103`, "The
    /// committed move"). The one-way law's form with
    /// each age replaced by the distance from the station read.
    pub fn modulus_derivative(&self, station: usize, cells: &[Option<usize>]) -> Vec<Rat> {
        let data = self.data(station, cells);
        let mass: Rat = data
            .iter()
            .map(|(distance, count, _)| &self.powers[*distance as usize] * count)
            .sum();
        let mean: Rat = data
            .iter()
            .map(|(distance, count, _)| {
                &self.powers[*distance as usize] * count * Rat::from_integer(BigInt::from(*distance))
            })
            .sum::<Rat>()
            / &mass;
        // [agent-inferred, October 1] Each datum's slope and each product are held at
        // `DERIVATIVE_BITS` significant bits toward zero: the exact entries carry the transported
        // mass's denominators (powers of `ρ` over thousands of bits), and the exact products cost
        // 603,039 ms of a 635,681 ms forced read at the opening. Every consumer already reads the
        // derivative at a grain (the joint direction at `JOINT_BITS`, the witness's `δ` at 128 bits).
        let held = |x: Rat| -> Rat {
            if x.is_zero() {
                x
            } else if x.is_negative() {
                -crate::holon::deposition::significant(&-x, DERIVATIVE_BITS, false)
            } else {
                crate::holon::deposition::significant(&x, DERIVATIVE_BITS, false)
            }
        };
        let mut derivative = vec![Rat::zero(); self.pairs.len()];
        for (distance, _, read) in data {
            let weight = &self.powers[distance as usize] / &mass;
            let slope =
                held(weight * (Rat::from_integer(BigInt::from(distance)) - &mean) / &self.modulus);
            if slope.is_zero() {
                continue;
            }
            for (value, add) in derivative.iter_mut().zip(read) {
                *value += held(add * &slope);
            }
        }
        derivative
    }

    /// [definition; agent-inferred, October 2; the
    /// [joined move's record](../../../../research/records/2026-10-02_THE_TRANSPORT_MODULUS_JOINS_THE_RECEIVERS_MINIMUM_ENERGY_MOVE.md)]
    /// **Each datum's reach slope** read from a station, aligned with [`BankPlacement::weights`]:
    /// `s_k = (r_k − r̄)/ρ`, the log-derivative of datum `k`'s transported weight in the modulus,
    /// `∂w_k/∂ρ = w_k s_k` (the factor [`BankPlacement::modulus_derivative`] applies), with `r̄` the
    /// span's weighted mean distance at the exact weights. Each slope is held at the derivative's
    /// grain. The request's phases come first, then the placed stations (`None` where unplaced).
    #[allow(clippy::type_complexity)]
    pub fn reach_slopes(
        &self,
        station: usize,
        cells: &[Option<usize>],
    ) -> (Vec<Rat>, Vec<Option<Rat>>) {
        let data = self.data(station, cells);
        let mass: Rat = data
            .iter()
            .map(|(distance, count, _)| &self.powers[*distance as usize] * count)
            .sum();
        let mean: Rat = data
            .iter()
            .map(|(distance, count, _)| {
                &self.powers[*distance as usize] * count * Rat::from_integer(BigInt::from(*distance))
            })
            .sum::<Rat>()
            / &mass;
        let slope = |distance: u64| -> Rat {
            let x = (Rat::from_integer(BigInt::from(distance)) - &mean) / &self.modulus;
            if x.is_zero() {
                x
            } else if x.is_negative() {
                -crate::holon::deposition::significant(&-x, DERIVATIVE_BITS, false)
            } else {
                crate::holon::deposition::significant(&x, DERIVATIVE_BITS, false)
            }
        };
        (
            self.reads
                .iter()
                .map(|(lag, _, _)| slope(Self::request_distance(station, *lag)))
                .collect(),
            cells
                .iter()
                .enumerate()
                .map(|(placed, cell)| cell.map(|_| slope(Self::station_distance(station, placed))))
                .collect(),
        )
    }
}

/// The significant bits a storage derivative in `ρ` is held at ([`BankPlacement::modulus_derivative`]):
/// above every consumer's own grain (`JOINT_BITS = 128` in the joint direction, the witness's `δ` at
/// 128 bits).
const DERIVATIVE_BITS: u32 = 192;

/// [definition; agent-inferred, October 5; lane C's
/// [record](../../../../research/records/2026-10-05_THE_RELEASE_READS_THE_LOCATED_PAIR_ON_EQUAL_MATERIAL.md)]
/// **The pair contacts the source port holds closed**: the distances `δ ∈ [1, d)` of the receiving
/// ring at which some pair contact `y → x` has zero slip, `P^δ B e_y − (E − B) e_x = 0` with
/// `B e_y ≠ 0` (`hnn::executed::pair_slip`), `E` the material's source port and `B` the field's
/// declared one (`hnn::constitution::declared_source_port`). It is the located pair's deposit read
/// back from the material: the key's distance is read where its deposit left it, never declared by
/// the caller, and a port that carries no located pair (every opening) closes none. Only the
/// distance is read: which class follows which stays in `E`'s columns, where the bank's reading of
/// each candidate's pair storage meets it ([`BankPlacement::pair_storage`]). The closure is exact:
/// a later deposit that moves a located column opens its contact again.
pub fn closed_pairs(
    field: &Field,
    material: &impl FieldMaterial,
    ring: usize,
) -> Result<Vec<usize>, HnnError> {
    let Some(prior) = crate::hnn::constitution::declared_source_port(field, ring)? else {
        return Ok(Vec::new());
    };
    let port = material
        .source_port(ring)
        .ok_or(HnnError::MissingSourcePort { ring })?;
    if port.rows() != prior.rows() || port.columns() != prior.columns() {
        return Err(HnnError::Shape {
            what: "the source port against its declared prior",
            expected: prior.rows() * prior.columns(),
            found: port.rows() * port.columns(),
        });
    }
    let alphabet = field.alphabet();
    let column = |matrix: &crate::ratio::linear::ExactRatMatrix, class: usize| -> Result<Vec<Rat>, HnnError> {
        (0..matrix.rows())
            .map(|row| Ok(matrix.get(row, class)?.clone()))
            .collect()
    };
    // The classes whose column carries a learned part, and the prior's nonzero columns.
    let mut learned = Vec::new();
    for class in 0..alphabet {
        if column(port, class)? != column(&prior, class)? {
            learned.push(class);
        }
    }
    let mut antecedents = Vec::new();
    for class in 0..alphabet {
        if column(&prior, class)?.iter().any(|x| !x.is_zero()) {
            antecedents.push(class);
        }
    }
    let period = field.ring(ring).period() as usize;
    let mut closed = Vec::new();
    for offset in 1..period {
        let mut found = false;
        'pairs: for &x in &learned {
            for &y in &antecedents {
                let slip = crate::hnn::executed::pair_slip(field, ring, port, &prior, offset, (y, x))?;
                if slip.iter().all(Zero::is_zero) {
                    found = true;
                    break 'pairs;
                }
            }
        }
        if found {
            closed.push(offset);
        }
    }
    Ok(closed)
}

// -------------------------------------------------------------------------------------------
// the physical repair

/// [definition; agent-inferred, October 5; lane C's physical repair, module header "The physical
/// repair"] **A damaged section as the field reads it**: the admitted encoded intact runs, each at
/// its declared station (its first cell's placement on the section's clock), over a declared
/// section of `length` stations and one complete producing chart. An erased station holds nothing: no
/// class, no clock step and no count. The section holds no erased class, so no truth of an erased
/// cell can reach the forward consumer ([`repair_by_field`]), and the reference repair's families
/// stay outside it (the grader's).
#[derive(Clone, Debug, PartialEq)]
pub struct DamagedSection {
    length: usize,
    /// The producing chart only: an empty part retains its decoder, labels, fibre and conduct,
    /// and no occurrence, including when the damage erased every station.
    chart: Encoded,
    runs: Vec<(usize, Encoded)>,
}

impl DamagedSection {
    /// **The damage**: an encoded passage with its erased cells dropped, cut into its intact runs
    /// (`Encoded::part`, each keeping the encoding that produced it). It is the transition that
    /// drops the erased cells, so their classes leave with it. Refused with an erasure past the
    /// passage.
    pub fn damage(encoded: &Encoded, erased: &[usize]) -> Result<Self, HnnError> {
        let length = encoded.len();
        if let Some(&t) = erased.iter().find(|&&t| t >= length) {
            return Err(HnnError::Shape {
                what: "an erasure within the passage",
                expected: length,
                found: t,
            });
        }
        let mut runs = Vec::new();
        let mut t = 0;
        while t < length {
            if erased.contains(&t) {
                t += 1;
                continue;
            }
            let start = t;
            while t < length && !erased.contains(&t) {
                t += 1;
            }
            runs.push((start, encoded.part(start..t)?));
        }
        Self::of_runs(length, encoded, runs)
    }

    /// **Intact runs at declared stations** over a section of `length` stations in the producing
    /// `chart`: refused when a run is empty, overlaps another, lies past the section, or has another
    /// producing chart. [agent-inferred] Comparing empty parts compares all chart operands, including
    /// `D`, labels and conduct, without comparing or retaining occurrences. Equal class counts alone
    /// do not supply the join. The `chart` operand's cells are dropped, never read.
    pub fn of_runs(
        length: usize,
        chart: &Encoded,
        mut runs: Vec<(usize, Encoded)>,
    ) -> Result<Self, HnnError> {
        let chart = chart.part(0..0)?;
        runs.sort_by_key(|(start, _)| *start);
        let mut end = 0;
        for (start, run) in &runs {
            let next = start.checked_add(run.len()).ok_or(HnnError::Unadmitted {
                reason: "an intact run's end is outside the station carrier",
            })?;
            if run.is_empty() || *start < end || next > length {
                return Err(HnnError::Shape {
                    what: "intact runs, nonempty and disjoint, within the section",
                    expected: length,
                    found: next,
                });
            }
            if run.part(0..0)? != chart {
                return Err(HnnError::Unadmitted {
                    reason: "intact runs do not share the section's complete producing chart",
                });
            }
            end = next;
        }
        Ok(Self {
            length,
            chart,
            runs,
        })
    }

    /// The declared stations `L`.
    pub fn length(&self) -> usize {
        self.length
    }

    /// The encoding's classes.
    pub fn classes(&self) -> usize {
        self.chart.classes()
    }

    /// **The complete producing chart**, with no occurrences. It survives total erasure, so
    /// neither the class domain nor the source/decoder/clock contract is guessed from intact data.
    pub fn chart(&self) -> &Encoded {
        &self.chart
    }

    /// The intact runs, each at its first station.
    pub fn runs(&self) -> &[(usize, Encoded)] {
        &self.runs
    }

    /// **The declared chart**: each intact station's class, `None` at each erasure.
    pub fn placed(&self) -> Vec<Option<usize>> {
        let mut cells = vec![None; self.length];
        for (start, run) in &self.runs {
            for (k, class) in run.classes_read().enumerate() {
                cells[start + k] = Some(class);
            }
        }
        cells
    }

    /// The erased stations, in order.
    pub fn erased(&self) -> Vec<usize> {
        self.placed()
            .iter()
            .enumerate()
            .filter_map(|(t, cell)| cell.is_none().then_some(t))
            .collect()
    }

    /// [definition; agent-inferred] **The supported source/decoder square at the consumer.**
    /// `D = I_A`, `lambda(c) = c`; the physical source map consumes these same classes and `R`
    /// returns their complex readings. The identity's selective source clock agrees with
    /// `tau_g + 1 + j` only when every class fits its source and no predecessor can advance, hence
    /// no predecessor can deliver a carry. Erased classes then leave time declared but inject
    /// nothing. Located advances, even on an intact section, cannot be replaced by this square.
    /// A sparse located-clock fibre and its projection through the producing `D` remain owed.
    /// All admission runs before the fresh source section and the physical word's opening.
    pub(crate) fn admit(&self, field: &Field, material: &dyn FieldMaterial, phases: &ReceivingPhases) -> Result<(), HnnError> {
        field.admit(&self.chart)?;
        if self.chart.located().is_some() {
            return Err(HnnError::Unadmitted {
                reason: "the located conduct has no certified sparse station-clock chart",
            });
        }
        if self.classes() != field.alphabet()
            || !self.chart.fibre().is_empty()
            || self.chart.decoder() != &crate::ratio::linear::ExactRatMatrix::identity(self.classes())?
            || self.runs.iter().any(|(_, run)| run.cells().iter().any(|&cell| run.label(cell) != Some(cell.class())))
        {
            return Err(HnnError::Unadmitted {
                reason: "the physical source and receiver do not share the producing identity decoder's classes",
            });
        }
        for &source in field.sources() {
            if (0..self.classes()).any(|class| !field.ring(source).fits(field.ring(source).port(class)))
                || (0..source).any(|ring| (0..self.classes()).any(|class| field.ring(ring).fits(field.ring(ring).port(class))))
            {
                return Err(HnnError::Unadmitted {
                    reason: "the identity conduct does not certify one source tick per declared station",
                });
            }
            let map = material.source_port(source).ok_or(HnnError::Unadmitted {
                reason: "the station chart has no physical source map",
            })?;
            if map.columns() != self.classes() || map.rows() != field.ring(source).width() {
                return Err(HnnError::Unadmitted {
                    reason: "the physical source map does not consume the producing chart's classes",
                });
            }
            for &offset in field.offsets() {
                let pair = material.pair_port(source, offset).ok_or(HnnError::Unadmitted {
                    reason: "the station chart has no declared physical pair port",
                })?;
                if pair.outputs().iter().any(|row| row.len() != field.ring(source).width())
                    || pair.current_reads().iter().chain(pair.earlier_reads())
                        .any(|row| row.len() != self.classes())
                {
                    return Err(HnnError::Unadmitted {
                        reason: "the physical pair port does not consume the producing chart's classes",
                    });
                }
            }
        }
        let ring = phases.ring();
        let map = material.receiving_map(ring).ok_or(HnnError::MissingReceivingMap { ring })?;
        if map.rows() != 2 * self.classes() || map.columns() != field.ring(ring).width() {
            return Err(HnnError::Unadmitted {
                reason: "the physical receiving map does not return the producing chart's complex classes",
            });
        }
        Ok(())
    }
}

/// [definition; agent-inferred, October 5] **One station's read at its bound crossing**: the
/// station `j`, the local crossing that reads it (`e = e_0 + j`, the receiver's phase `j`:
/// `hnn::receiving`, "The receiver reads the passage by epochs"), the refinement clock's tick there
/// (`opened_at + e`), and the read `R · P_R^(τ_R) v_R(e)` at the receiver's grain
/// ([`ReceivingPhases::read`]).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StationRead {
    pub station: usize,
    pub crossing: usize,
    pub tick: usize,
    pub read: ReceivingRead,
}

impl StationRead {
    /// **The point reading's leading classes at the grain**: the classes whose grain cell
    /// `(carry, phase class)` is the largest. A reading of one executed state, never a fibre: a
    /// point reading does not certify the domain of the coupled drive, so no release reads it.
    pub fn leaders(&self) -> Vec<usize> {
        let cells = &self.read.cells;
        let Some(top) = cells.iter().map(|cell| (&cell.carry, cell.phase)).max() else {
            return Vec::new();
        };
        cells
            .iter()
            .enumerate()
            .filter(|(_, cell)| (&cell.carry, cell.phase) == top)
            .map(|(class, _)| class)
            .collect()
    }
}

/// [definition] **Why an erased station is held.**
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Unresolved {
    /// No crossing of the declared receiving section reads the station.
    Unread,
    /// A crossing reads it, but no owner certifies the domain of the word's coupled drive that the
    /// decoder would project (#62), so the domain is the whole state space.
    UncertifiedDomain,
    /// The coupled source-completion enclosure reaches more than one decoded class.
    PluralDomain,
}

/// The receiving image of every compatible completion. The coordinate bounds also include the
/// actual sparse reading; that point is an executed observation, not a possible completed source.
/// `classes` encloses the completed sources' grain leaders. A shared one-hot response can certify
/// their exact union without losing correlations to a coordinate box.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PhysicalDomainRead {
    pub logits: Vec<crate::ratio::algebraic::ExactInterval>,
    pub classes: Vec<usize>,
    pub completion: Option<PhysicalCompletionRead>,
}

/// A transient receiving certificate for one erased station: its label is the same one-hot
/// coordinate in every first/pair source port, full field state and receiving row. For label c,
/// the complete reading is `fixed_logits + label_logits[c]`. These are signed linear response
/// columns, not completed Words, candidate answers or retained occurrence states.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PhysicalCompletionRead {
    pub station: usize,
    pub fixed_logits: Vec<Rat>,
    pub label_logits: Vec<Vec<Rat>>,
}

/// [definition] **One station after the physical repair**: intact as admitted, released at width
/// zero, or held with its fibre and the reason it is unresolved.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RepairedCell {
    Intact(usize),
    Released(usize),
    Held {
        fibre: Vec<usize>,
        unresolved: Unresolved,
    },
}

impl RepairedCell {
    /// The station's class, when it has one.
    pub fn class(&self) -> Option<usize> {
        match self {
            Self::Intact(class) | Self::Released(class) => Some(*class),
            Self::Held { .. } => None,
        }
    }
}

/// [definition] **The physical repair's return**: each station's cell, each bound station's read,
/// the source opening's work receipt, every executed full tick's field balance, the word's balance
/// and the carried end at its last crossing ([`Word::reception_end`]). The word itself, its
/// per-tick passage and its waves, is dropped inside [`repair_by_field`] once read.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PhysicalRepair {
    pub cells: Vec<RepairedCell>,
    pub reads: Vec<StationRead>,
    /// None when the admitted source transport or executed operands have no enclosure here.
    /// These receiving receipts are not a retained trajectory or a reusable material certificate.
    pub domains: Vec<Option<PhysicalDomainRead>>,
    pub opening: SourceOpeningReceipt,
    pub balances: Vec<FieldBalance>,
    pub word: WordBalance,
    pub carry: ReceptionCarry,
}

/// **Repair a damaged section by the field's own motion** (module header, "The physical repair"):
/// the admitted intact runs placed on the declared chart as one sparse source moment, imposed once
/// at the word's opening ([`Word::open_exact_received`]), the one continuing word run through the
/// declared receiver's crossings ([`Word::forward`]), each bound station read through the field's
/// decoder at its grain ([`ReceivingPhases::read`], material alone), and each erased station
/// decided by `receiver::release` at tolerance zero over the classes its domain's projection
/// admits. Refused when a run is not admitted (`Field::admit`), when the opening's work does not
/// close, or when the executed crossings are not the declared section's clock. Producing charts,
/// the identity station clock and both physical maps are admitted before the word opens.
pub fn repair_by_field(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
    phases: &ReceivingPhases,
) -> Result<PhysicalRepair, HnnError> {
    physical_forward(field, material, current, section, opening, phases, true, None)
        .map(|(prediction, _word, _source, _observation)| prediction)
}

/// The one physical forward law, shared by a blind repair and a blind reception awaiting its
/// observed comparison. Only the latter retains the transient Word and source moment until the
/// paired return consumes them; neither path receives a target.
fn physical_forward<'f>(
    field: &'f Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
    phases: &ReceivingPhases,
    completion_domain: bool,
    observer: Option<&crate::hnn::receiving::SourceObserverView>,
) -> Result<
    (
        PhysicalRepair,
        Word<'f>,
        SourceMoment,
        Option<crate::hnn::receiving::SourceObserverReceipt>,
    ),
    HnnError,
> {
    if let Some(view) = observer {
        view.admits(field, material, current)?;
        if completion_domain || phases != view.phases() || section.length != phases.aperture() {
            return Err(HnnError::Unadmitted {
                reason: "a complete observer section without a completion-domain release",
            });
        }
    } else if material.receiving_carrier(phases.ring())
        != crate::hnn::receiving::ReceivingCarrier::Anchor
    {
        return Err(HnnError::Unadmitted {
            reason: "a raw-anchor forward cannot read source-observer material",
        });
    }
    section.admit(field, material, phases)?;
    // The admitted identity's conduct certifies station j at τ_g + 1 + j on each source ring.
    let placed = section.placed();
    let mut source = SourceMoment::open_with(field, current, material)?;
    for &ring in field.sources() {
        source = source.station_section(field, current, ring, &placed)?;
    }
    // One accounted imposition, then the one continuing word through the declared crossings.
    let (mut word, opening_receipt) =
        Word::open_exact_received(field, material, current, &source, opening)?;
    let (anchors, domains) = if completion_domain {
        physical_domain_forward(field, material, current, section, phases, &mut word)?
    } else {
        // Exact sparse comparison control: the same admitted source and native Word, without
        // the additional source-completion certificate. Missing stations remain Uncertified.
        (word.forward(phases)?, vec![None; phases.aperture()])
    };
    let balances = word.field_balances().to_vec();
    let carry = word.reception_end()?;
    let balance = WordBalance::of(&word.released()?);
    let opened_at = word.opened_at();
    // The clock certificate: the carried end stands at the last declared crossing's tick and the
    // word's own hop clock, which counts the crossings scattered, one past it, so crossing e is
    // the refinement's tick opened_at + e (the placement alone certifies no clock).
    let last = opened_at + phases.last_epoch();
    if carry.ticks != last
        || word.clock().ticks() != num_bigint::BigUint::from(last + 1)
        || anchors.len() != phases.aperture()
    {
        return Err(HnnError::ContinuingState {
            what: "the executed crossings are not the declared receiving section's clock",
        });
    }
    let observation = observer.map(|view| view.read(&word)).transpose()?;
    let first = phases.first_epoch();
    let reads = if let Some(observation) = &observation {
        observation
            .features
            .iter()
            .enumerate()
            .map(|(station, feature)| {
                Ok(StationRead {
                    station,
                    crossing: first + station,
                    // H_j's section is provenance; all six physical anchors exist only here.
                    tick: observation.available_at,
                    read: phases.read_observer(field, material, current, feature)?,
                })
            })
            .collect::<Result<Vec<_>, HnnError>>()?
    } else {
        anchors
            .iter()
            .take(section.length)
            .enumerate()
            .map(|(station, anchor)| {
                Ok(StationRead {
                    station,
                    crossing: first + station,
                    tick: opened_at + first + station,
                    read: phases.read(field, material, current, anchor)?,
                })
            })
            .collect::<Result<Vec<_>, HnnError>>()?
    };
    let admitted = domain_classes(section);
    let cells = placed
        .iter()
        .enumerate()
        .map(|(t, cell)| match cell {
            Some(class) => Ok(RepairedCell::Intact(*class)),
            None if !completion_domain => Ok(RepairedCell::Held {
                fibre: admitted.clone(),
                unresolved: Unresolved::UncertifiedDomain,
            }),
            None => decide_station(
                t,
                domains
                    .get(t)
                    .and_then(Option::as_ref)
                    .map_or(admitted.as_slice(), |domain| domain.classes.as_slice()),
                if t >= reads.len() {
                    Unresolved::Unread
                } else if domains[t].is_some() {
                    Unresolved::PluralDomain
                } else {
                    Unresolved::UncertifiedDomain
                },
            ),
        })
        .collect::<Result<Vec<_>, HnnError>>()?;
    Ok((
        PhysicalRepair {
            cells,
            reads,
            domains,
            opening: opening_receipt,
            balances,
            word: balance,
            carry,
        },
        word,
        source,
        observation,
    ))
}

/// [agent-inferred] One executed Word and its compatible source family. An exact linear,
/// one-hole source carries a fixed state and shared signed response columns through each native
/// tick. Otherwise the finite tube uses `|x_t-x_t^sparse|<=r_t` and the actual producing maps.
/// Both routes include the contemporary entered interior, junction, element, loaded return,
/// contact and actual pump tick; neither is a cyclic lock or an authored task answer.
fn physical_domain_forward(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    phases: &ReceivingPhases,
    word: &mut Word<'_>,
) -> Result<(Vec<Vec<Rat>>, Vec<Option<PhysicalDomainRead>>), HnnError> {
    let mut completion = physical_completion_opening(field, material, current, section, word)?;
    let mut radius = if completion.is_none() {
        physical_opening_radius(field, material, current, section, word)?
    } else {
        None
    };
    let mut domains = Vec::with_capacity(phases.aperture());
    for crossing in 0..phases.junction_steps() {
        let point = word.change()?;
        let junctions = radius
            .as_ref()
            .map(|radius| physical_junction_radius(word.operands(), radius))
            .transpose()?;
        if phases.epochs().contains(&crossing) {
            domains.push(if let Some(completion) = &completion {
                Some(physical_completion_read(
                    field,
                    material,
                    current,
                    phases,
                    word.operands(),
                    &point,
                    completion,
                )?)
            } else {
                match &junctions {
                    Some(junctions) => {
                        let ring = phases.ring();
                        let operands = word.operands();
                        let incoming: Vec<_> = operands
                            .incident(ring)
                            .iter()
                            .map(|&a| point.arrivals[a][operands.end_slot(a, ring)].as_slice())
                            .collect();
                        let anchor = crate::hnn::propagation::participation(
                            operands.weights(ring),
                            &point.storage[ring],
                            &incoming,
                        )?;
                        Some(physical_domain_read(
                            field,
                            material,
                            current,
                            phases,
                            &anchor,
                            &junctions[ring].anchor,
                        )?)
                    }
                    None => None,
                }
            });
        }
        if crossing + 1 == phases.junction_steps() {
            word.last_junction()?;
        } else {
            if let Some(completion) = &mut completion {
                completion.fixed = physical_signed_tick(
                    word.operands(),
                    &completion.fixed,
                    word.opened_at() + crossing,
                )?;
                for column in &mut completion.labels {
                    *column =
                        physical_signed_tick(word.operands(), column, word.opened_at() + crossing)?;
                }
            }
            radius = match (&radius, &junctions) {
                (Some(radius), Some(junctions)) => Some(physical_tick_radius(
                    word,
                    &point,
                    radius,
                    junctions,
                    word.opened_at() + crossing,
                )?),
                _ => None,
            };
            word.tick()?;
        }
    }
    let anchors = phases
        .epochs()
        .map(|crossing| {
            word.anchor(crossing, phases.ring())
                .map(<[Rat]>::to_vec)
                .ok_or(HnnError::WordEnded {
                    ticks: word.ticks(),
                })
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok((anchors, domains))
}

/// The executed operand law has no approximate inverse, transient split or loaded chart residual.
/// Shared by the coupled-domain bound and the affine source-port comparison certificate.
fn physical_word_is_exact(operands: &crate::hnn::propagation::Operands) -> bool {
    operands.lattice().is_none()
        && operands.rings().iter().all(|ring| ring.chart().is_none())
        && operands.contacts().iter().all(|contact| contact.chart().is_none())
        && operands.resonators().iter().flatten().all(|ring| {
            (0..ring.phases()).all(|phase| {
                ring.chart_words(phase).is_none() && ring.certificate(phase).is_zero()
            })
        })
}

/// An affine source family transported in lockstep with the one executed Word. The fixed state
/// includes its actual entered interior; all response columns start with zero interior. No
/// completed source is constructed, and no response opens or advances a candidate Word.
struct PhysicalCompletionColumns {
    station: usize,
    fixed: crate::hnn::word::EndChange,
    labels: Vec<crate::hnn::word::EndChange>,
}

/// [agent-inferred] At one missing station h, the full first population N and every offset's
/// population max(N-delta,0) are class independent. Known terms form s_bar; E e_c and the pair
/// edges incident on h form column z_c, so s(c)=s_bar+z_c. The same one-hot e_c is shared by
/// every source, offset and phase. This is the existing station_section/PairPort law expanded
/// before an absolute bound; two missing endpoints require bilinear cross terms and use the
/// conservative tube. Rounded/leaky ports and nonlinear Words also use that existing tube.
fn physical_completion_opening(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    word: &Word<'_>,
) -> Result<Option<PhysicalCompletionColumns>, HnnError> {
    let operands = word.operands();
    let placed = section.placed();
    let holes: Vec<_> = placed
        .iter()
        .enumerate()
        .filter(|(_, cell)| cell.is_none())
        .map(|(station, _)| station)
        .collect();
    if holes.len() != 1
        || !physical_word_is_exact(operands)
        || operands
            .resonators()
            .iter()
            .flatten()
            .any(|ring| ring.material().saturation().is_some())
        || field
            .sources()
            .iter()
            .any(|&ring| !material.transport(ring).is_one())
    {
        return Ok(None);
    }
    let chart = PopulationChart::of(field);
    let population = u64::try_from(section.length).map_err(|_| HnnError::CountOverflow)?;
    let weight = chart.value(population);
    let mut fixed = word.change()?;
    let mut labels: Vec<_> = (0..section.classes())
        .map(|_| crate::hnn::word::EndChange::rest(field, operands))
        .collect();
    for &ring in field.sources() {
        let geometry = field.ring(ring);
        let map = material
            .source_port(ring)
            .ok_or(HnnError::MissingSourcePort { ring })?;
        let phase = current.phase(field, ring)? as usize;
        let period = geometry.placements().len();
        let carried = |station: usize, values: &[Rat]| {
            let at = (phase + 1 + station % period) % period;
            geometry.rotate(values, &(&current.lift()[ring] - BigInt::from(at)))
        };
        fixed.storage[ring].fill(Rat::zero());
        for (station, class) in placed.iter().enumerate() {
            let column = |class: usize| -> Result<Vec<Rat>, HnnError> {
                let values = (0..geometry.width())
                    .map(|row| Ok(&weight * map.get(row, class)?))
                    .collect::<Result<Vec<_>, HnnError>>()?;
                Ok(carried(station, &values))
            };
            match class {
                Some(class) => {
                    fixed.storage[ring] =
                        crate::ratio::linear::vector::add(&fixed.storage[ring], &column(*class)?)
                }
                None => {
                    for (class, label) in labels.iter_mut().enumerate() {
                        label.storage[ring] = crate::ratio::linear::vector::add(
                            &label.storage[ring],
                            &column(class)?,
                        );
                    }
                }
            }
        }
        for &offset in field.offsets() {
            let pair = material
                .pair_port(ring, offset)
                .ok_or(HnnError::MissingSourcePort { ring })?;
            if pair
                .outputs()
                .iter()
                .any(|row| row.len() != geometry.width())
                || pair
                    .current_reads()
                    .iter()
                    .chain(pair.earlier_reads())
                    .any(|row| row.len() != section.classes())
            {
                return Err(HnnError::Unadmitted {
                    reason: "the affine completion's pair relation must match its producing class and ring chart",
                });
            }
            let pair_weight = chart.value(
                u64::try_from(section.length.saturating_sub(offset))
                    .map_err(|_| HnnError::CountOverflow)?,
            );
            for station in offset..section.length {
                let earlier = station - offset;
                let column = |x: usize, y: usize| {
                    let mut values = vec![Rat::zero(); geometry.width()];
                    for ((output, a), b) in pair
                        .outputs()
                        .iter()
                        .zip(pair.current_reads())
                        .zip(pair.earlier_reads())
                    {
                        let factor = &pair_weight * &a[x] * &b[y];
                        for (value, entry) in values.iter_mut().zip(output) {
                            *value += &factor * entry;
                        }
                    }
                    carried(station, &values)
                };
                match (placed[station], placed[earlier]) {
                    (Some(x), Some(y)) => {
                        fixed.storage[ring] =
                            crate::ratio::linear::vector::add(&fixed.storage[ring], &column(x, y))
                    }
                    (x, y) => {
                        for (class, label) in labels.iter_mut().enumerate() {
                            label.storage[ring] = crate::ratio::linear::vector::add(
                                &label.storage[ring],
                                &column(x.unwrap_or(class), y.unwrap_or(class)),
                            );
                        }
                    }
                }
            }
        }
    }
    Ok(Some(PhysicalCompletionColumns {
        station: holes[0],
        fixed,
        labels,
    }))
}

/// Signed junction and full tick of the admitted linear relation. The native element,
/// resonator and contact owners supply the images at the actual pump tick. In particular, the
/// rate, displacement, velocity and arriving waves remain correlated with their source label.
fn physical_signed_junctions(
    operands: &crate::hnn::propagation::Operands,
    state: &crate::hnn::word::EndChange,
) -> Result<Vec<crate::hnn::propagation::Junction>, HnnError> {
    (0..operands.rings().len())
        .map(|ring| {
            let incoming: Vec<_> = operands
                .incident(ring)
                .iter()
                .map(|&a| state.arrivals[a][operands.end_slot(a, ring)].as_slice())
                .collect();
            let anchor = crate::hnn::propagation::participation(
                operands.weights(ring),
                &state.storage[ring],
                &incoming,
            )?;
            Ok(crate::hnn::propagation::scattering_about(
                anchor,
                &state.storage[ring],
                &incoming,
            ))
        })
        .collect()
}

pub(crate) fn physical_signed_tick(
    operands: &crate::hnn::propagation::Operands,
    state: &crate::hnn::word::EndChange,
    tick: usize,
) -> Result<crate::hnn::word::EndChange, HnnError> {
    let junctions = physical_signed_junctions(operands, state)?;
    let mut next = state.clone();
    for (ring, junction) in junctions.iter().enumerate() {
        let drive = crate::hnn::propagation::element_step(
            &operands.rings()[ring],
            &junction.storage_wave,
            &junction.contrast,
        )?
        .next;
        if let Some(resonator) = &operands.resonators()[ring] {
            let local = state.resonators[ring]
                .as_ref()
                .ok_or(HnnError::ContinuingState {
                    what: "the affine completion needs the full producing resonator state",
                })?;
            let driven = resonator.step(
                tick,
                &drive,
                [&local[0], &local[1]],
                &crate::hnn::ring::ResonatorRemainders::default(),
                None,
            )?;
            next.storage[ring] = driven.output;
            next.resonators[ring] = Some(driven.state);
            next.resonator_phases[ring] = Some(resonator.phase_at(tick));
        } else {
            next.storage[ring] = drive;
        }
    }
    for (a, contact) in operands.contacts().iter().enumerate() {
        let (from, to) = contact.ends();
        let outgoing = |ring: usize| {
            &junctions[ring].outgoing[operands
                .incident(ring)
                .iter()
                .position(|&index| index == a)
                .unwrap()]
        };
        let passed = crate::hnn::propagation::transit(
            contact,
            operands.step(),
            outgoing(from),
            outgoing(to),
            &state.states[a][0],
            &state.states[a][1],
        )?;
        next.arrivals[a] = [passed.arrive_from, passed.arrive_to];
        next.states[a] = [passed.displacement, passed.rate];
    }
    Ok(next)
}

fn physical_completion_read(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    phases: &ReceivingPhases,
    operands: &crate::hnn::propagation::Operands,
    point: &crate::hnn::word::EndChange,
    completion: &PhysicalCompletionColumns,
) -> Result<PhysicalDomainRead, HnnError> {
    let anchor = |state: &crate::hnn::word::EndChange| -> Result<Vec<Rat>, HnnError> {
        let ring = phases.ring();
        let incoming: Vec<_> = operands
            .incident(ring)
            .iter()
            .map(|&a| state.arrivals[a][operands.end_slot(a, ring)].as_slice())
            .collect();
        crate::hnn::propagation::participation(
            operands.weights(ring),
            &state.storage[ring],
            &incoming,
        )
    };
    let fixed_logits = phases
        .read(field, material, current, &anchor(&completion.fixed)?)?
        .logits;
    let label_logits = completion
        .labels
        .iter()
        .map(|column| {
            Ok(phases
                .read(field, material, current, &anchor(column)?)?
                .logits)
        })
        .collect::<Result<Vec<_>, HnnError>>()?;
    let sparse = phases
        .read(field, material, current, &anchor(point)?)?
        .logits;
    let mut logits: Vec<_> = sparse
        .into_iter()
        .map(|value| crate::ratio::algebraic::ExactInterval {
            lower: value.clone(),
            upper: value,
        })
        .collect();
    let mut classes = std::collections::BTreeSet::new();
    // The support of an affine map on a one-hot face is a row reduction over its columns, not
    // A^holes candidate executions. Read the shared coefficient at the actual grain first;
    // independent coordinate extrema would invent leaders no compatible source produces.
    for column in &label_logits {
        let image = crate::ratio::linear::vector::add(&fixed_logits, column);
        for (interval, value) in logits.iter_mut().zip(&image) {
            interval.lower = interval.lower.clone().min(value.clone());
            interval.upper = interval.upper.clone().max(value.clone());
        }
        let cells: Vec<_> = (0..field.alphabet())
            .map(|class| crate::receiver::face::GrainCell::of(&image[2 * class], phases.grain()))
            .collect();
        let top = cells
            .iter()
            .map(|cell| (&cell.carry, cell.phase))
            .max()
            .unwrap();
        classes.extend(
            cells
                .iter()
                .enumerate()
                .filter(|(_, cell)| (&cell.carry, cell.phase) == top)
                .map(|(class, _)| class),
        );
    }
    Ok(PhysicalDomainRead {
        logits,
        classes: classes.into_iter().collect(),
        completion: Some(PhysicalCompletionRead {
            station: completion.station,
            fixed_logits,
            label_logits,
        }),
    })
}

/// Consume the applied source perturbation through the same producing Word as the adjoint. Only
/// one signed full-state response is propagated; no candidate Word, replay or target enters it.
/// The selected source-only successor has already passed `physical_source_only_change`.
pub(super) fn physical_source_pairing(
    field: &Field,
    before: &crate::hnn::constitution::Constitution,
    after: &crate::hnn::constitution::Constitution,
    current: &Current,
    phases: &ReceivingPhases,
    source: &SourceMoment,
    operands: &crate::hnn::propagation::Operands,
    opened_at: usize,
    prediction: &PhysicalRepair,
    covector: &crate::hnn::ratio::RatioCovector,
    back: &crate::hnn::port::WordReturn,
    compared: &[bool],
    applied: &PhysicalSourceCertificate,
) -> Result<PhysicalSourcePairing, HnnError> {
    use crate::ratio::linear::vector::{dot, sub};
    if !physical_word_is_exact(operands)
        || !prediction.word.bound.is_zero()
        || back.released.entries != 0
    {
        return Err(HnnError::Unadmitted {
            reason: "the source-return pairing has no zero-defect numerical contract",
        });
    }
    if source.opening() != current.lift() {
        return Err(HnnError::Unadmitted {
            reason: "the source-return pairing has a foreign source opening frame",
        });
    }
    if back.opening.len() != field.rings().len()
        || back.opening.iter().zip(field.rings()).any(|(row, ring)| row.len() != ring.width())
        || covector.logits().len() != phases.aperture()
        || prediction.reads.len() != phases.aperture()
        || compared.len() != phases.aperture()
    {
        return Err(HnnError::Unadmitted {
            reason: "the source-return pairing does not share the producing section's shape",
        });
    }
    let last_station = compared.iter().rposition(|&crossed| crossed).ok_or(HnnError::Unadmitted {
        reason: "the source-return pairing has no compared receiving crossing",
    })?;
    for (station, crossing) in phases.epochs().enumerate() {
        let actual = &prediction.reads[station];
        let tick = opened_at.checked_add(crossing).ok_or(HnnError::Unadmitted {
            reason: "the source-return pairing's producing clock exceeds its carrier",
        })?;
        if actual.station != station || actual.crossing != crossing || actual.tick != tick
            || covector.logits()[station].len() != 2 * field.alphabet()
            || (!compared[station] && covector.logits()[station].iter().any(|g| !g.is_zero()))
        {
            return Err(HnnError::Unadmitted {
                reason: "the source-return pairing is not bound to the executed comparison crossings",
            });
        }
    }
    let last_crossing = phases.first_epoch() + last_station;
    let old_open = source.open_storage(field, before, current)?;
    let new_open = source.open_storage(field, after, current)?;
    let delta: Vec<Vec<Rat>> = new_open.iter().zip(&old_open)
        .map(|(new, old)| sub(new, old)).collect();
    let opening: Rat = back.opening.iter().zip(&delta).map(|(g, d)| dot(g, d)).sum();
    let source_move_squared: Rat = delta.iter().map(|row| dot(row, row)).sum();
    // This is a perturbation of the source storage only. Its zero interior is the difference of
    // two identical entered physical states, not a reset of the production reception.
    let mut response = crate::hnn::word::EndChange::rest(field, operands);
    response.storage = delta;
    let mut crossings = Vec::new();
    let mut receiving = Rat::zero();
    // The declared partition needs no response after its last compared crossing.
    for crossing in 0..=last_crossing {
        if crossing >= phases.first_epoch() {
            let station = crossing - phases.first_epoch();
            if compared[station] {
                let ring = phases.ring();
                let incoming: Vec<_> = operands.incident(ring).iter()
                    .map(|&a| response.arrivals[a][operands.end_slot(a, ring)].as_slice())
                    .collect();
                let anchor = crate::hnn::propagation::participation(
                    operands.weights(ring), &response.storage[ring], &incoming,
                )?;
                // Use the actual read owner: its same R, current lift and complex row chart.
                let logits = phases.read(field, before, current, &anchor)?.logits;
                let pairing = dot(&covector.logits()[station], &logits);
                receiving += &pairing;
                crossings.push(PhysicalSourceCrossing {
                    station, crossing, tick: prediction.reads[station].tick, pairing,
                    logit_move_squared: dot(&logits, &logits),
                });
            }
        }
        if crossing < last_crossing {
            response = physical_signed_tick(operands, &response, opened_at + crossing)?;
        }
    }
    let deposition = -&applied.joint.decrease;
    let defect = &receiving - &opening;
    let composition_defect = &opening - &deposition;
    if !defect.is_zero() || !composition_defect.is_zero() {
        return Err(HnnError::Unadmitted {
            reason: "the applied source move fails its same-Word receiving/opening/deposition pairing",
        });
    }
    Ok(PhysicalSourcePairing {
        producing_commit: before.commit(), source_lift: current.lift().to_vec(),
        receiver: phases.ring(), opened_at, junction_steps: phases.junction_steps(),
        response_ticks: last_crossing,
        source_move_squared, crossings, receiving, opening, deposition, defect,
        composition_defect, return_remainders: back.released.clone(),
    })
}

/// All physical forward relations except the selected source relations stay fixed. The field/current and
/// imposition are the same borrowed operands. FieldMaterial exposes E's map, never its normal-law
/// carried remainder; SourceMoment::open_storage consumes precisely that view.
fn physical_source_only_change(
    field: &Field,
    before: &dyn FieldMaterial,
    after: &dyn FieldMaterial,
    selected: &[crate::hnn::constitution::Locus],
    selected_pairs: &[(usize, usize)],
) -> bool {
    use crate::hnn::constitution::Locus;
    field.rings().iter().enumerate().all(|(ring, _)| {
        before.standing(ring) == after.standing(ring)
            && before.passive_factor(ring) == after.passive_factor(ring)
            && before.contrast_port(ring) == after.contrast_port(ring)
            && before.slices(ring) == after.slices(ring)
            && before.receiving_map(ring) == after.receiving_map(ring)
            && before.ring_resonator(ring) == after.ring_resonator(ring)
            && before.transport(ring) == after.transport(ring)
            && (selected.contains(&Locus::SourcePort(ring))
                || before.source_port(ring) == after.source_port(ring))
            && field.offsets().iter().all(|&offset| {
                let old = before.pair_port(ring, offset);
                let new = after.pair_port(ring, offset);
                if selected_pairs.contains(&(ring, offset)) {
                    old.zip(new).is_some_and(|(old, new)| {
                        old.current_reads() == new.current_reads()
                            && old.earlier_reads() == new.earlier_reads()
                    })
                } else {
                    old == new
                }
            })
    }) && field.contacts().iter().enumerate().all(|(contact, _)| {
        before.contact_storage(contact) == after.contact_storage(contact)
            && before.contact_stiffness(contact) == after.contact_stiffness(contact)
            && before.contact_dissipation(contact) == after.contact_dissipation(contact)
            && before.contact_stiffness_signature(contact)
                == after.contact_stiffness_signature(contact)
            && before.contact_surface_storage(contact) == after.contact_surface_storage(contact)
    })
}

/// Read the applied output-row move on the same pair tables that produced the source.
/// The read factors are fixed by the caller's executable other-relation check, hence this is
/// the actual affine output difference, including any budgeted output carry/release.
fn physical_pair_output_certificate(
    field: &Field,
    before: &dyn FieldMaterial,
    after: &dyn FieldMaterial,
    source: &SourceMoment,
    steps: &[crate::hnn::constitution::FactorStep],
    publication: &crate::hnn::constitution::DepositReading,
) -> Result<PhysicalSourceCertificate, HnnError> {
    use crate::hnn::constitution::{FactorGradient, Family, Locus};
    let mut groups = std::collections::BTreeMap::<usize, Vec<_>>::new();
    for step in steps {
        let FactorGradient::PairPort { ring, offset, outputs, .. } = &step.gradient else {
            return Err(HnnError::Unadmitted {
                reason: "the pair-output certificate contains another factor relation",
            });
        };
        groups.entry(*ring).or_default().push((*offset, outputs));
    }
    let mut sources = Vec::new();
    for (ring, pairs) in groups {
        let geometry = field.ring(ring);
        let mut by_phase = vec![vec![Rat::zero(); geometry.width()]; geometry.placements().len()];
        let (mut alignment, mut gain) = (Rat::zero(), Rat::zero());
        for (offset, gradient) in pairs {
            let old = before.pair_port(ring, offset).ok_or(HnnError::MissingSourcePort { ring })?;
            let new = after.pair_port(ring, offset).ok_or(HnnError::MissingSourcePort { ring })?;
            alignment += gradient.iter().flatten()
                .zip(old.outputs().iter().flatten().zip(new.outputs().iter().flatten()))
                .map(|(g, (old, new))| g * (new - old)).sum::<Rat>();
            let reading = publication.steps.iter().find(|(at, read)| {
                *at == Locus::SourcePort(ring) && read.family == Family::Pair(offset)
            }).ok_or(HnnError::Unadmitted {
                reason: "the pair-output successor has no physical source gain reading",
            })?;
            gain = gain.max(reading.1.gain.clone());
            if let Some(table) = source.offset_table(field, ring, offset)? {
                for (phase, moved) in by_phase.iter_mut().enumerate() {
                    let old = old.apply_table(&table, phase, field.alphabet(), geometry.width());
                    let new = new.apply_table(&table, phase, field.alphabet(), geometry.width());
                    for (value, (old, new)) in moved.iter_mut().zip(old.iter().zip(new)) {
                        *value += new - old;
                    }
                }
            }
        }
        let moves: Rat = by_phase.iter().flatten().map(|value| value * value).sum();
        let bound = crate::holon::deposition::root_ceiling(&(&gain * &moves));
        sources.push(PhysicalSourceMove { ring, alignment, moves, gain, bound });
    }
    let one = Rat::one();
    let joint = crate::holon::deposition::JointReading::read(&crate::ratio::rat(1, 2),
        sources.iter().map(|source| (&one, &source.alignment, &source.bound)));
    if !joint.holds() {
        return Err(HnnError::Unadmitted {
            reason: "the actual carried pair-output move fails its physical joint-step certificate",
        });
    }
    Ok(PhysicalSourceCertificate { sources, joint })
}

/// The box is derived, never chosen: complete every missing station with any admitted class,
/// at the same source clock and population chart; unite that image with the actual sparse open.
/// The unit source has its sharper station-column bound. A leaky source uses the actual rounded
/// phase features' coordinate extrema, with its complete extent and class-independent mass.
fn physical_opening_radius(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    word: &Word<'_>,
) -> Result<Option<crate::hnn::word::EndChange>, HnnError> {
    let operands = word.operands();
    if !physical_word_is_exact(operands) {
        return Ok(None);
    }
    let point = word.change()?;
    let mut radius = crate::hnn::word::EndChange::rest(field, operands);
    let population = u64::try_from(section.length).map_err(|_| HnnError::Unadmitted {
        reason: "the completion population must fit its declared source chart",
    })?;
    let weight = PopulationChart::of(field).value(population);
    let placed = section.placed();
    for &ring in field.sources() {
        if !material.transport(ring).is_one() {
            let Some((lower, upper)) =
                physical_leaky_source_bounds(field, material, current, section, ring)?
            else { return Ok(None) };
            for coordinate in 0..field.ring(ring).width() {
                radius.storage[ring][coordinate] = (&lower[coordinate]
                    - &point.storage[ring][coordinate])
                    .abs()
                    .max((&upper[coordinate] - &point.storage[ring][coordinate]).abs());
            }
            continue;
        }
        let geometry = field.ring(ring);
        let map = material
            .source_port(ring)
            .ok_or(HnnError::MissingSourcePort { ring })?;
        let mut lower = vec![Rat::zero(); geometry.width()];
        let mut upper = lower.clone();
        for (station, class) in placed.iter().enumerate() {
            // P^tau P^(-(tau+1+j)) E_c: the already admitted station-clock square.
            let columns = match class {
                Some(class) => vec![*class],
                None => (0..section.classes()).collect(),
            };
            let values = columns
                .iter()
                .map(|&class| {
                    let column = (0..map.rows())
                        .map(|row| map.get(row, class).cloned())
                        .collect::<Result<Vec<_>, _>>()?;
                    Ok(geometry.rotate(&column, &-(BigInt::from(station) + BigInt::one())))
                })
                .collect::<Result<Vec<_>, HnnError>>()?;
            for coordinate in 0..geometry.width() {
                lower[coordinate] += values.iter().map(|value| &value[coordinate]).min().unwrap();
                upper[coordinate] += values.iter().map(|value| &value[coordinate]).max().unwrap();
            }
        }
        let Some((pair_lower, pair_upper)) =
            physical_pair_source_bounds(field, material, current, section, ring)?
        else { return Ok(None) };
        for coordinate in 0..geometry.width() {
            radius.storage[ring][coordinate] = (&weight * &lower[coordinate] + &pair_lower[coordinate]
                - &point.storage[ring][coordinate])
                .abs()
                .max((&weight * &upper[coordinate] + &pair_upper[coordinate]
                    - &point.storage[ring][coordinate]).abs());
        }
    }
    Ok(Some(radius))
}

/// [agent-inferred] The admitted identity clock fixes every complete source's extent `N`.
/// Its entering integer weight `nearest(U*rho^(N-1-j))` and total mass are independent of class.
/// For one phase/class coordinate, assigning every hole to that class maximizes its count;
/// assigning every hole to another class minimizes it. The actual population chart is monotone,
/// so the `A` monochrome supports attain every coordinate endpoint, including chart rounding.
/// The normalizer reads that common mass, not a class-specific or learned total. This claim is
/// tied to the actual fresh continued-source law, not an arbitrary future normalizer.
/// Each support opens empty, continues this source once, and immediately reads its mass and
/// normalized features with immutable current: no intervening ingest, clock synchronization
/// or aging. The actual forward uses the same fresh source shape before the Word copies it.
/// They are transient source-coordinate supports, not executed candidate Words or task answers.
/// Signed E and the producing phase lift map their box to an opening enclosure. Discarding joint
/// coordinate correlations can widen that enclosure, never shrink the admitted source family.
fn physical_leaky_source_bounds(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    section: &DamagedSection,
    ring: usize,
) -> Result<Option<(Vec<Rat>, Vec<Rat>)>, HnnError> {
    let geometry = field.ring(ring);
    let modulus = material.transport(ring);
    let open = SourceMoment::open_with(field, current, material)?;
    let placed = section.placed();
    let mut bounds: Option<(Vec<Vec<Rat>>, Vec<Vec<Rat>>)> = None;
    let mut phase_population = None;
    let mut transported_mass: Option<BigInt> = None;
    for class in 0..section.classes() {
        let support: Vec<_> = placed.iter().map(|cell| Some(cell.unwrap_or(class))).collect();
        let moment = open.continued(field, current, ring, &support)?;
        let Some(mass) = moment.transported_mass(ring)? else { return Ok(None) };
        if (section.length != 0 && mass <= BigInt::zero())
            || transported_mass.as_ref().is_some_and(|before| before != &mass)
        {
            return Ok(None);
        }
        transported_mass = Some(mass);
        // These supports measure first marginals only. The separate ordered-pair box below
        // consumes the joint family; monochrome supports cannot bound mixed pair slots.
        for &offset in field.offsets() {
            if moment.pair_population(ring, offset)? != 0 {
                return Ok(None);
            }
        }
        let population = (0..geometry.placements().len())
            .map(|phase| Ok(moment.phase_counts(ring, phase)?.iter().sum::<u64>()))
            .collect::<Result<Vec<_>, HnnError>>()?;
        if phase_population.as_ref().is_some_and(|before| before != &population) {
            return Ok(None);
        }
        phase_population = Some(population);
        let features = (0..geometry.placements().len())
            .map(|phase| moment.normalized_counts(field, ring, phase, &modulus))
            .collect::<Result<Vec<_>, _>>()?;
        if let Some((lower, upper)) = &mut bounds {
            for ((lower, upper), row) in lower.iter_mut().zip(upper).zip(features) {
                for ((lower, upper), value) in lower.iter_mut().zip(upper).zip(row) {
                    *lower = lower.clone().min(value.clone());
                    *upper = upper.clone().max(value);
                }
            }
        } else {
            bounds = Some((features.clone(), features));
        }
    }
    let (features_lower, features_upper) = bounds.ok_or(HnnError::Unadmitted {
        reason: "the physical source completion chart has no class",
    })?;
    let map = material.source_port(ring).ok_or(HnnError::MissingSourcePort { ring })?;
    let mut lower = vec![Rat::zero(); geometry.width()];
    let mut upper = lower.clone();
    for phase in 0..geometry.placements().len() {
        let lift = &current.lift()[ring] - BigInt::from(phase);
        for class in 0..section.classes() {
            let column = (0..map.rows())
                .map(|row| map.get(row, class).cloned())
                .collect::<Result<Vec<_>, _>>()?;
            let column = geometry.rotate(&column, &lift);
            for coordinate in 0..geometry.width() {
                let at_lower = &column[coordinate] * &features_lower[phase][class];
                let at_upper = &column[coordinate] * &features_upper[phase][class];
                lower[coordinate] += at_lower.clone().min(at_upper.clone());
                upper[coordinate] += at_lower.max(at_upper);
            }
        }
    }
    let Some((pair_lower, pair_upper)) =
        physical_pair_source_bounds(field, material, current, section, ring)?
    else { return Ok(None) };
    for coordinate in 0..geometry.width() {
        lower[coordinate] += &pair_lower[coordinate];
        upper[coordinate] += &pair_upper[coordinate];
    }
    Ok(Some((lower, upper)))
}

/// The declared pair ports on the complete source family's ordered-coordinate box. Their
/// signed coefficients are combined before interval mapping, including cancellations between
/// rank members. Phase/lift is the producing source's same transport square. This bounds
/// every complete pair table, independently of first marginals; shared-hole correlations only
/// widen the box. The opening radius also contains the separate actual sparse source point.
#[allow(clippy::type_complexity)]
fn physical_pair_source_bounds(
    field: &Field, material: &dyn FieldMaterial, current: &Current,
    section: &DamagedSection, ring: usize,
) -> Result<Option<(Vec<Rat>, Vec<Rat>)>, HnnError> {
    let geometry = field.ring(ring);
    let a = section.classes();
    let placed = section.placed();
    let open = SourceMoment::open_with(field, current, material)?;
    let mut lower = vec![Rat::zero(); geometry.width()];
    let mut upper = lower.clone();
    for &offset in field.offsets() {
        let Some((feature_lower, feature_upper)) =
            open.station_pair_bounds(field, current, ring, &placed, offset)?
        else { return Ok(None) };
        let pair = material.pair_port(ring, offset).ok_or(HnnError::MissingSourcePort { ring })?;
        for phase in 0..geometry.placements().len() {
            let lift = &current.lift()[ring] - BigInt::from(phase);
            for slot in 0..a*a {
                if feature_upper[phase][slot].is_zero() { continue }
                let (x, y) = (slot/a, slot%a);
                let mut column = vec![Rat::zero(); geometry.width()];
                for rho in 0..pair.rank() {
                    let coefficient = &pair.current_reads()[rho][x] * &pair.earlier_reads()[rho][y];
                    for (entry, output) in column.iter_mut().zip(&pair.outputs()[rho]) {
                        *entry += &coefficient * output;
                    }
                }
                let column = geometry.rotate(&column, &lift);
                for coordinate in 0..geometry.width() {
                    let at_lower = &column[coordinate] * &feature_lower[phase][slot];
                    let at_upper = &column[coordinate] * &feature_upper[phase][slot];
                    lower[coordinate] += at_lower.clone().min(at_upper.clone());
                    upper[coordinate] += at_lower.max(at_upper);
                }
            }
        }
    }
    Ok(Some((lower, upper)))
}

fn physical_add_radius(left: &[Rat], right: &[Rat]) -> Vec<Rat> {
    left.iter()
        .zip(right)
        .map(|(left, right)| left + right)
        .collect()
}

fn physical_scale_radius(scale: &Rat, vector: &[Rat]) -> Vec<Rat> {
    vector.iter().map(|value| scale.abs() * value).collect()
}

fn physical_matrix_radius(
    map: &crate::ratio::linear::ExactRatMatrix,
    radius: &[Rat],
) -> Result<Vec<Rat>, HnnError> {
    (0..map.rows())
        .map(|row| {
            (0..map.columns())
                .map(|column| Ok(map.get(row, column)?.abs() * &radius[column]))
                .sum::<Result<Rat, HnnError>>()
        })
        .collect()
}

fn physical_junction_radius(
    operands: &crate::hnn::propagation::Operands,
    radius: &crate::hnn::word::EndChange,
) -> Result<Vec<crate::hnn::propagation::Junction>, HnnError> {
    (0..operands.rings().len())
        .map(|ring| {
            let incoming: Vec<_> = operands
                .incident(ring)
                .iter()
                .map(|&a| radius.arrivals[a][operands.end_slot(a, ring)].as_slice())
                .collect();
            let anchor = crate::hnn::propagation::participation(
                operands.weights(ring),
                &radius.storage[ring],
                &incoming,
            )?;
            // [agent-inferred] The reflected port is already an operand of the anchor.
            // Preserve 2*w_p - delta_(p,port) before taking absolute values. Bounding
            // 2*anchor - port as independent terms would invent a drive variation:
            // with one equal-admittance contact, 2*w_s-1=0, not 2*w_s+1=2.
            let reflected = |port: usize, scale: &Rat| {
                let weights: Vec<_> = operands
                    .weights(ring)
                    .iter()
                    .enumerate()
                    .map(|(p, weight)| {
                        (scale * weight - if p == port { Rat::one() } else { Rat::zero() }).abs()
                    })
                    .collect();
                crate::hnn::propagation::participation(&weights, &radius.storage[ring], &incoming)
            };
            Ok(crate::hnn::propagation::Junction {
                storage_wave: reflected(0, &crate::ratio::integer(2))?,
                contrast: reflected(0, &Rat::one())?,
                outgoing: incoming
                    .iter()
                    .enumerate()
                    .map(|(port, _)| reflected(port + 1, &crate::ratio::integer(2)))
                    .collect::<Result<Vec<_>, _>>()?,
                anchor,
            })
        })
        .collect()
}

/// Image of a linear element relation under a coordinate box. The relation itself supplies the
/// columns, so the enclosure shares its native operands instead of authoring another transit.
fn physical_linear_radius(
    inputs: &[&[Rat]],
    output: usize,
    apply: impl Fn(&[Vec<Rat>]) -> Result<Vec<Rat>, HnnError>,
) -> Result<Vec<Rat>, HnnError> {
    let mut basis: Vec<_> = inputs
        .iter()
        .map(|input| vec![Rat::zero(); input.len()])
        .collect();
    let mut image = vec![Rat::zero(); output];
    for (part, radius) in inputs.iter().enumerate() {
        for (coordinate, value) in radius
            .iter()
            .enumerate()
            .filter(|(_, value)| !value.is_zero())
        {
            basis[part][coordinate] = Rat::one();
            let column = apply(&basis)?;
            basis[part][coordinate] = Rat::zero();
            for (image, coefficient) in image.iter_mut().zip(column) {
                *image += value * coefficient.abs();
            }
        }
    }
    Ok(image)
}

fn physical_tick_radius(
    word: &Word<'_>,
    point: &crate::hnn::word::EndChange,
    radius: &crate::hnn::word::EndChange,
    junctions: &[crate::hnn::propagation::Junction],
    tick: usize,
) -> Result<crate::hnn::word::EndChange, HnnError> {
    let operands = word.operands();
    let mut next = radius.clone();
    let h = operands.step();
    for (ring, junction) in junctions.iter().enumerate() {
        let drive = physical_linear_radius(
            &[&junction.storage_wave, &junction.contrast],
            operands.rings()[ring].width(),
            |basis| {
                Ok(crate::hnn::propagation::element_step(
                    &operands.rings()[ring],
                    &basis[0],
                    &basis[1],
                )?
                .next)
            },
        )?;
        let Some(resonator) = &operands.resonators()[ring] else {
            next.storage[ring] = drive;
            continue;
        };
        let state = point.resonators[ring]
            .as_ref()
            .ok_or(HnnError::ContinuingState {
                what: "the coupled enclosure needs the producing resonator state",
            })?;
        let state_radius = radius.resonators[ring]
            .as_ref()
            .ok_or(HnnError::ContinuingState {
                what: "the coupled enclosure needs both resonator coordinate radii",
            })?;
        let phase = resonator.phase_at(tick);
        let (capacity, _, _) = resonator.material().forms();
        let nonlinear = resonator.material().saturation();
        let factor = if nonlinear.is_some() {
            crate::ratio::integer(1)
        } else {
            crate::ratio::integer(2)
        };
        let mut right = physical_add_radius(
            &physical_scale_radius(
                &factor,
                &physical_matrix_radius(capacity, &state_radius[1])?,
            ),
            &physical_scale_radius(h, &drive),
        );
        let mut force = physical_matrix_radius(resonator.stiffness(phase), &state_radius[0])?;
        if let Some(law) = nonlinear {
            // On each complex node, |H_Q(u)| <= H_Q(U), U_i=|u_i^sparse|+r_i.
            // This bounds the actual quartic effort difference over the entire box, including
            // its cross-coordinate terms, and joins the state-dependent drive to that force.
            let largest: Vec<_> = state[0]
                .iter()
                .zip(&state_radius[0])
                .map(|(value, radius)| value.abs() + radius)
                .collect();
            force = physical_add_radius(
                &force,
                &physical_matrix_radius(&law.hessian(&largest)?, &state_radius[0])?,
            );
        }
        right = physical_add_radius(&right, &physical_scale_radius(h, &force));
        let rate = physical_matrix_radius(&resonator.operator(phase).inverse()?, &right)?;
        let displacement = physical_add_radius(&state_radius[0], &physical_scale_radius(h, &rate));
        let velocity = if nonlinear.is_some() {
            rate.clone()
        } else {
            physical_add_radius(
                &physical_scale_radius(&crate::ratio::integer(2), &rate),
                &state_radius[1],
            )
        };
        next.resonators[ring] = Some([displacement, velocity]);
        next.storage[ring] = physical_add_radius(
            &drive,
            &physical_scale_radius(&(crate::ratio::integer(2) / resonator.admittance()), &rate),
        );
    }
    for (a, contact) in operands.contacts().iter().enumerate() {
        let (from, to) = contact.ends();
        let outgoing = |ring: usize| {
            &junctions[ring].outgoing[operands
                .incident(ring)
                .iter()
                .position(|&index| index == a)
                .unwrap()]
        };
        let inputs = [
            outgoing(from).as_slice(),
            outgoing(to).as_slice(),
            radius.states[a][0].as_slice(),
            radius.states[a][1].as_slice(),
        ];
        let n_from = inputs[0].len();
        let n_to = inputs[1].len();
        let n_state = contact.width();
        let image = physical_linear_radius(&inputs, n_from + n_to + 2 * n_state, |basis| {
            let passed = crate::hnn::propagation::transit(
                contact, h, &basis[0], &basis[1], &basis[2], &basis[3],
            )?;
            Ok([
                passed.arrive_from,
                passed.arrive_to,
                passed.displacement,
                passed.rate,
            ]
            .concat())
        })?;
        next.arrivals[a] = [
            image[..n_from].to_vec(),
            image[n_from..n_from + n_to].to_vec(),
        ];
        next.states[a] = [
            image[n_from + n_to..n_from + n_to + n_state].to_vec(),
            image[n_from + n_to + n_state..].to_vec(),
        ];
    }
    Ok(next)
}

fn physical_domain_read(
    field: &Field,
    material: &dyn FieldMaterial,
    current: &Current,
    phases: &ReceivingPhases,
    anchor: &[Rat],
    radius: &[Rat],
) -> Result<PhysicalDomainRead, HnnError> {
    let point = phases.read(field, material, current, anchor)?;
    let ring = phases.ring();
    let transported: Vec<_> = field
        .ring(ring)
        .rotate(radius, &current.lift()[ring])
        .into_iter()
        .map(|value| value.abs())
        .collect();
    let radius = physical_matrix_radius(
        material
            .receiving_map(ring)
            .ok_or(HnnError::MissingReceivingMap { ring })?,
        &transported,
    )?;
    let logits: Vec<_> = point
        .logits
        .iter()
        .zip(&radius)
        .map(|(point, radius)| crate::ratio::algebraic::ExactInterval {
            lower: point - radius,
            upper: point + radius,
        })
        .collect();
    let lower = (0..field.alphabet())
        .map(|class| crate::receiver::face::GrainCell::of(&logits[2 * class].lower, phases.grain()))
        .collect::<Vec<_>>();
    let upper = (0..field.alphabet())
        .map(|class| crate::receiver::face::GrainCell::of(&logits[2 * class].upper, phases.grain()))
        .collect::<Vec<_>>();
    let greatest_lower = lower
        .iter()
        .map(|cell| (&cell.carry, cell.phase))
        .max()
        .unwrap();
    // Every native grain leader belongs to this fibre. One member therefore certifies the
    // producing identity decoder's class reading throughout the compatible family.
    let classes = upper
        .iter()
        .enumerate()
        .filter(|(_, cell)| (&cell.carry, cell.phase) >= greatest_lower)
        .map(|(class, _)| class)
        .collect();
    Ok(PhysicalDomainRead { logits, classes, completion: None })
}

/// A blind reception through the declared source-relative observer. The same physical forward
/// owner executes the sparse source and retains the actual carry. Observer availability is the
/// final crossing, not the earlier source-response section assigned to each feature.
pub struct SourceObserverPrediction<'f, 'm> {
    field: &'f Field,
    material: &'m crate::hnn::receiving::SourceObserverMaterial,
    current: Current,
    chart: Encoded,
    word: Word<'f>,
    prediction: PhysicalRepair,
    observation: crate::hnn::receiving::SourceObserverReceipt,
}

/// No teacher or erased class enters this constructor. It supports completed four-cell sections
/// only. All six anchors belong to this Word at or before opened_at+3. A future communication
/// request has no admission here. Completion domains are withheld, so every erasure stays Held.
pub fn predict_by_source_observer<'f, 'm>(
    field: &'f Field,
    material: &'m crate::hnn::receiving::SourceObserverMaterial,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
) -> Result<SourceObserverPrediction<'f, 'm>, HnnError> {
    let view = material.view();
    view.admits(field, material.constitution(), current)?;
    if section.length != view.phases().aperture() {
        return Err(HnnError::Unadmitted {
            reason: "the observer reads a complete four-cell section, not a future station",
        });
    }
    let (prediction, word, source, observation) = physical_forward(
        field,
        material.constitution(),
        current,
        section,
        opening,
        view.phases(),
        false,
        Some(view),
    )?;
    let mut observation = observation.ok_or(HnnError::Unadmitted {
        reason: "the declared observer's actual forward receipt",
    })?;
    observation.producing_commit = Some(material.commit());
    let imposed = source.open_storage(field, material.constitution(), current)?;
    if observation.source != imposed[0] {
        return Err(HnnError::Unadmitted {
            reason: "the executed observer disagrees with the actual blind source imposition",
        });
    }
    Ok(SourceObserverPrediction {
        field,
        material,
        current: current.clone(),
        chart: section.chart.clone(),
        word,
        prediction,
        observation,
    })
}

/// The observer's reached R comparison. The full opening adjoint is an exterior receipt;
/// no Word, source occurrence or target is installed in the successor material.
/// This type exposes neither a pair/source deposit nor the generic material ticks: the
/// observer's material-dependent coefficients have not been differentiated.
#[derive(Debug)]
pub struct SourceObserverTeaching {
    pub prediction: PhysicalRepair,
    pub observation: crate::hnn::receiving::SourceObserverReceipt,
    pub full_adjoint: CurrentSourceReceivingReturn,
    pub ratio: crate::hnn::ratio::HolonRatio,
    pub material: crate::hnn::receiving::SourceObserverMaterial,
    pub publication: crate::hnn::constitution::DepositReading,
    pub samples: Vec<crate::hnn::constitution::Sample>,
}

/// The complete opening-state derivative of this **current-source-only R objective** at
/// fixed physical body and observer coefficients. This is an exterior observation receipt,
/// not a context-dependent continuation objective, a retention quotient, or a material return.
/// Pair/body/source learning must not consume it as the complete learning return: that join
/// additionally owes the observer-coefficient and comparison derivatives at their operands.
///
/// ```compile_fail,E0308
/// use holonics::hnn::prediction::CurrentSourceReceivingReturn;
/// use holonics::hnn::port::WordReturn;
/// fn cannot_deposit_generic_material(returned: CurrentSourceReceivingReturn) {
///     let _: WordReturn = returned;
/// }
/// ```
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CurrentSourceReceivingReturn {
    opening: crate::hnn::port::ChangeCovector,
}

impl CurrentSourceReceivingReturn {
    /// Read the full opening-state pairing receipt. This does not expose material ticks or
    /// provide a conversion to the generic Word return consumed by compose_return.
    pub fn opening(&self) -> &crate::hnn::port::ChangeCovector {
        &self.opening
    }
}

#[derive(Debug)]
pub struct SourceObserverRefusal {
    pub prediction: PhysicalRepair,
    pub observation: crate::hnn::receiving::SourceObserverReceipt,
    pub error: HnnError,
}

impl SourceObserverPrediction<'_, '_> {
    pub fn prediction(&self) -> &PhysicalRepair {
        &self.prediction
    }
    pub fn observation(&self) -> &crate::hnn::receiving::SourceObserverReceipt {
        &self.observation
    }
    pub fn finish(self) -> PhysicalRepair {
        self.prediction
    }

    /// One carrier through blind read, observed ratio, located-prior preparation and normal
    /// deposition. Only R is stepped. The actual Word receives all six transposed anchor seeds
    /// in one reverse sweep; replacing it with the old source marginal fails the full identity.
    /// The declared observation is a current-source comparison in this completed section.
    /// This owner makes no sufficiency claim for targets that depend on retained interior
    /// context; its physical carry continues without being substituted for a context view.
    pub fn observe(
        self,
        contemporary: &crate::hnn::receiving::SourceObserverMaterial,
        observed: &Encoded,
        compared: &[bool],
    ) -> Result<SourceObserverTeaching, SourceObserverRefusal> {
        use crate::hnn::constitution::{LinearLocus, LinearStep, Locus, Reach, Sample};
        use crate::hnn::port::Deposit;
        use crate::hnn::ratio::{Faces, HolonRatio, target_phases};
        let Self {
            field,
            material,
            current,
            chart,
            word,
            prediction,
            observation,
        } = self;
        let result = (|| -> Result<_, HnnError> {
            if contemporary != material {
                return Err(HnnError::Unadmitted {
                    reason: "the observer comparison's producing view/material changed",
                });
            }
            if observed.part(0..0)? != chart
                || observed.len() != observation.features.len()
                || compared.len() != observation.features.len()
                || !compared.iter().any(|&crossed| crossed)
            {
                return Err(HnnError::Unadmitted {
                    reason: "the observer comparison's producing chart and nonempty section partition",
                });
            }
            let targets: Vec<_> = observed.classes_read().collect();
            if prediction.cells.iter().zip(&targets).any(
                |(cell, target)| matches!(cell, RepairedCell::Intact(class) if class != target),
            ) {
                return Err(HnnError::Unadmitted {
                    reason: "the observed comparison changed an intact source clamp",
                });
            }
            let view = material.view();
            let theta = material.constitution();
            let phases = view.phases();
            let reads: Vec<_> = prediction
                .reads
                .iter()
                .map(|station| station.read.clone())
                .collect();
            let ratio = HolonRatio::compare_partition(
                Faces::of_reads(&reads, phases.grain())?,
                &targets,
                &target_phases(field, current.lift(), phases.ring(), observed)?,
                compared,
            )?;
            let gradient = ratio.covector()?;
            let map = theta
                .receiving_map(phases.ring())
                .ok_or(HnnError::MissingReceivingMap {
                    ring: phases.ring(),
                })?;
            let lift = &current.lift()[phases.ring()];
            let expected_source = view.source_covector(gradient.logits(), map, lift)?;
            let seeds = view.source_seeds(&expected_source)?;
            let (back, full) = word.pull_back_joined(seeds)?;
            // Differentiate the entire actual opening, including every arriving wave and
            // contact state. An old raw-anchor return has nonzero interior columns here.
            if full.storage[0] != expected_source
                || full.storage.iter().skip(1).flatten().any(|x| !x.is_zero())
                || full
                    .arrivals
                    .iter()
                    .flatten()
                    .flatten()
                    .any(|x| !x.is_zero())
                || full.states.iter().flatten().flatten().any(|x| !x.is_zero())
                || full.resonators.iter().any(Option::is_some)
                || !back.released.total.is_zero()
            {
                return Err(HnnError::Unadmitted {
                    reason: "the observer's full-state matched return identity fails",
                });
            }
            // The generic material ticks are NOT published: chi depends on body material,
            // whose coefficient derivative is outside this R-only receiving declaration.
            let samples: Vec<_> = observation
                .features
                .iter()
                .zip(gradient.logits())
                .zip(compared)
                .filter_map(|((feature, gradient), &crossed)| {
                    crossed.then(|| Sample {
                        weight: Rat::one(),
                        feature: field.ring(0).rotate(feature, lift),
                        covector: gradient.iter().map(|x| -x).collect(),
                        masses: None,
                    })
                })
                .collect();
            let locus = Locus::ReceivingMap(phases.ring());
            let reach = Reach {
                receiver: phases.ring(),
                stations: vec![observation.available_at as u64],
                entries: vec![observation.anchors[0].2 as u64],
                phases: samples.len() as u64,
                loci: [locus].into_iter().collect(),
            };
            let deposit = Deposit::new(
                theta.commit(),
                vec![LinearStep {
                    locus: LinearLocus::Receiving(phases.ring()),
                    samples: samples.clone(),
                }],
                Vec::new(),
                vec![locus],
            )
            .with_reach(reach);
            let (successor, publication) = theta.deposited(&deposit)?;
            if publication.loci.iter().any(|at| *at != locus) {
                return Err(HnnError::Unadmitted {
                    reason: "the observer's R-only comparison reached another material relation",
                });
            }
            let successor = material.successor(field, &current, successor)?;
            Ok((ratio, full, successor, publication, samples))
        })();
        match result {
            Ok((ratio, full_adjoint, material, publication, samples)) => {
                Ok(SourceObserverTeaching {
                    prediction,
                    observation,
                    full_adjoint: CurrentSourceReceivingReturn {
                        opening: full_adjoint,
                    },
                    ratio,
                    material,
                    publication,
                    samples,
                })
            }
            Err(error) => Err(SourceObserverRefusal {
                prediction,
                observation,
                error,
            }),
        }
    }
}

/// [definition] A participating reception awaiting one observed comparison: its blind receipt,
/// current frame, producing chart and transient native Word/source moment. It is consumed by
/// `observe` or `finish`, never cloned or retained as an occurrence archive. An observed target
/// cannot enter its forward constructor.
pub struct PhysicalPrediction<'f, 'm> {
    field: &'f Field,
    material: &'m crate::hnn::constitution::Constitution,
    current: Current,
    phases: ReceivingPhases,
    chart: Encoded,
    opening_support: Vec<usize>,
    source: SourceMoment,
    word: Word<'f>,
    prediction: PhysicalRepair,
}

/// Blind physical reception with the paired return still available. `repair_by_field` executes
/// the same law and drops that return; this constructor keeps it only until the immediate
/// comparison or `finish`. No reference family, observation or expected output is an input.
pub fn predict_by_field<'f, 'm>(
    field: &'f Field,
    material: &'m crate::hnn::constitution::Constitution,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
    phases: &ReceivingPhases,
) -> Result<PhysicalPrediction<'f, 'm>, HnnError> {
    physical_prediction(field, material, current, section, opening, phases, true)
}

/// Exact sparse forward and immediate same-Word comparison, matching the charted sparse law.
/// No source-completion certificate is computed: every erased station is Held. This explicit
/// control does not stand in for the complete-domain repair or certify a point leader as output.
pub fn predict_sparse_by_field<'f, 'm>(
    field: &'f Field,
    material: &'m crate::hnn::constitution::Constitution,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
    phases: &ReceivingPhases,
) -> Result<PhysicalPrediction<'f, 'm>, HnnError> {
    physical_prediction(field, material, current, section, opening, phases, false)
}

fn physical_prediction<'f, 'm>(
    field: &'f Field,
    material: &'m crate::hnn::constitution::Constitution,
    current: &Current,
    section: &DamagedSection,
    opening: &WordOpening,
    phases: &ReceivingPhases,
    completion_domain: bool,
) -> Result<PhysicalPrediction<'f, 'm>, HnnError> {
    let (prediction, word, source, _observation) =
        physical_forward(field, material, current, section, opening, phases, completion_domain, None)?;
    Ok(PhysicalPrediction {
        field,
        material,
        current: current.clone(),
        phases: phases.clone(),
        chart: section.chart.clone(),
        opening_support: opening.support(field),
        source,
        word,
        prediction,
    })
}

/// The observed comparison and its actual publication: the blind receipt remains the produced
/// reading. The successor is the normal law's certified deposit, not a replacement decoder.
#[derive(Debug)]
pub struct PhysicalTeaching {
    pub prediction: PhysicalRepair,
    pub ratio: crate::hnn::ratio::HolonRatio,
    pub pullback: crate::hnn::port::Pullback,
    pub constitution: crate::hnn::constitution::Constitution,
    pub publication: crate::hnn::constitution::DepositReading,
    /// Exterior feature-energy readings of exactly the admitted normal samples/factor family.
    /// A scalar diagnostic beside eta and the applied move, never a retained source or target.
    pub feature_energy: Vec<(crate::hnn::constitution::Locus, Rat)>,
    /// Exterior operands of the reached R return, before/after its actual publication.
    /// No receiving sample, normal-law snapshot or diagnostic enters retained physical state.
    pub receiving_diagnostic: Option<PhysicalReceivingDiagnostic>,
    /// The source consumer's certificate of its applied relation, including carried corrections.
    /// The normal publication's step readings describe its proposed ray separately.
    pub source_certificate: Option<PhysicalSourceCertificate>,
    /// The applied source move's forward/return pairing on the declared compared crossings.
    /// Present for exact-linear E/pair learning; R-only learning changes no source relation.
    pub source_pairing: Option<PhysicalSourcePairing>,
}

/// [definition; agent-inferred] The already reached receiving operands at one publication.
/// Each sample is `f=P_R^lift v_R`, `g=q-p` from the producing Word; the existing class metric
/// scales even covector entries only. `before` and `after` include the actual map, Gram, chart,
/// remainders and located pair. The publication separately carries eta, residual and PriorMove.
/// Consume `(R_after-R_before)f` at this SAME feature: it includes the actual prior move.
/// These are transient exterior receipts, never a retained tape or another forward/return call.
#[derive(Debug)]
pub struct PhysicalReceivingDiagnostic {
    pub producing_commit: u64,
    pub receiver: usize,
    pub source_lift: Vec<BigInt>,
    pub crossings: Vec<PhysicalReceivingCrossing>,
    pub samples: Vec<crate::hnn::constitution::Sample>,
    pub before: crate::hnn::constitution::NormalLaw,
    pub after: crate::hnn::constitution::NormalLaw,
}

/// A compared station's actual receiving clock, paired in order with the diagnostic sample.
#[derive(Debug)]
pub struct PhysicalReceivingCrossing {
    pub station: usize,
    pub crossing: usize,
    pub tick: usize,
}

/// One compared receiving crossing of the actual applied source perturbation, with R and the
/// producing Word fixed. These are exterior readings, never retained response states.
#[derive(Debug, PartialEq, Eq)]
pub struct PhysicalSourceCrossing {
    pub station: usize,
    pub crossing: usize,
    pub tick: usize,
    pub pairing: Rat,
    pub logit_move_squared: Rat,
}

/// [definition; agent-inferred] A consumed source/receiver contract for the applied E or pair
/// output move: delta_s = SourceMoment.open_storage(Theta') - open_storage(Theta), with the same
/// retained source counts, normalization, lift and entered interior. On compared crossings,
/// <g, R P^tau Pi F delta_s> = <Word.pull_back(g).opening, delta_s>
/// = -the applied deposition alignment. F uses the producing operands at opened_at + crossing.
/// This checks one applied direction and comparison, not the whole operator or unseen accuracy.
/// `defect` is the signed observable pairing defect; no energy defect is used as its bound.
/// The supported exact-linear law admits zero numerical defect and no adjoint remainder only.
#[derive(Debug, PartialEq, Eq)]
pub struct PhysicalSourcePairing {
    pub producing_commit: u64,
    pub source_lift: Vec<BigInt>,
    pub receiver: usize,
    pub opened_at: usize,
    pub junction_steps: usize,
    /// One signed full-field response step per crossing before the last compared read.
    pub response_ticks: usize,
    pub source_move_squared: Rat,
    pub crossings: Vec<PhysicalSourceCrossing>,
    pub receiving: Rat,
    pub opening: Rat,
    /// Negative first-order applied deposition alignment, not a finite score decrement.
    pub deposition: Rat,
    pub defect: Rat,
    pub composition_defect: Rat,
    pub return_remainders: crate::hnn::chart::Remainders,
}

/// One source law's actual applied feature moves and their physical source-to-receiver bound.
#[derive(Debug)]
pub struct PhysicalSourceMove {
    pub ring: usize,
    pub alignment: Rat,
    pub moves: Rat,
    pub gain: Rat,
    pub bound: Rat,
}

/// The existing joint-step law evaluated on the actual carried E maps or pair outputs, with R and the exact
/// linear Word fixed. A refused certificate publishes no successor and retains the blind carry.
#[derive(Debug)]
pub struct PhysicalSourceCertificate {
    pub sources: Vec<PhysicalSourceMove>,
    pub joint: crate::holon::deposition::JointReading,
}

/// A comparison refusal preserves the physical motion already reached, including the carry.
/// The unconsumed transient Word is dropped; no stale operands are held for replay.
#[derive(Debug)]
pub struct PhysicalTeachingRefusal {
    pub prediction: PhysicalRepair,
    pub error: HnnError,
}

/// One affine relation per observed comparison. The coupled R/E ray is not certified.
#[derive(Clone, Copy, PartialEq, Eq)]
enum PhysicalLearning {
    Receiving,
    SourcePorts,
    PairOutputs,
}

impl PhysicalPrediction<'_, '_> {
    /// Read the whole blind output before any teaching observation is admitted.
    pub fn prediction(&self) -> &PhysicalRepair {
        &self.prediction
    }

    /// An exterior read of one already executed receiving anchor, in the producing read's
    /// phase chart. It opens/scatters/returns nothing and keeps no occurrence for replay.
    pub fn receiving_feature(&self, station: usize) -> Option<Vec<Rat>> {
        let read = self.prediction.reads.get(station)?;
        let receiver = self.phases.ring();
        let anchor = self.word.anchor(read.crossing, receiver)?;
        Some(self.field.ring(receiver).rotate(anchor, &self.current.lift()[receiver]))
    }

    /// Finish without an observation, dropping the transient paired return.
    pub fn finish(self) -> PhysicalRepair {
        self.prediction
    }

    /// [definition; agent-inferred] An explicit observation after blind prediction, on a declared
    /// station partition. The supported comparison reads the whole section at its source/receiving
    /// ring; its identity conduct was certified by forward admission, so `target_phases` reads
    /// the same station clock. The target's producing chart must equal the source's.
    ///
    /// The ratio's covector passes through this Word's original operands and phase frame.
    /// `reference::compose_return` forms the reached normal samples (including R's actual rotated
    /// anchors and q-p). Only its reached receiving samples at compared stations are deposited;
    /// `Constitution::deposited` publishes their certified successor. Trees,
    /// a codec grader and a handcrafted decoder never enter it. A changed material refuses and
    /// requires a new contemporary forward reading; the old Word is never replayed.
    pub fn observe(
        self,
        contemporary: &crate::hnn::constitution::Constitution,
        observed: &Encoded,
        compared: &[bool],
    ) -> Result<PhysicalTeaching, PhysicalTeachingRefusal> {
        self.observe_at(
            contemporary,
            observed,
            compared,
            PhysicalLearning::Receiving,
            false,
        )
    }

    /// The same receiving comparison, with its already reached operands returned as an exterior
    /// diagnostic. It changes no normal sample, step, prior move, successor or physical carry.
    pub fn observe_receiving_diagnostic(
        self,
        contemporary: &crate::hnn::constitution::Constitution,
        observed: &Encoded,
        compared: &[bool],
    ) -> Result<PhysicalTeaching, PhysicalTeachingRefusal> {
        self.observe_at(contemporary, observed, compared, PhysicalLearning::Receiving, true)
    }

    /// An observed source-port comparison through the same blind Word, with R and every internal
    /// propagation relation fixed. E enters only at the next contemporary source opening. The
    /// existing source moment supplies its actual phase/population and, at leaky transport, its
    /// carried age weights; neither stations nor target values are installed as learned features.
    ///
    /// The supported ray is an exact linear Word. A reached quartic needs its Word-Hessian term
    /// before E can be stepped. Only nonzero reached source samples enter their existing normal
    /// laws. Their certificate reads the whole executed source-to-comparison diamond, including
    /// its element/contact growth, rather than just the stepped source locus.
    /// With these fixed exact linear operands, the consuming equation is
    /// `delta_logits_j = R P_R^tau T_j delta_source_open(E)`. Its adjoint pairs the same difference
    /// with the returned E gradient; the source gain bounds the compared logit moves by the
    /// occupied source features' squared moves. The native fixture checks both on the physical
    /// Word. Map-carry remainders need not vanish: the existing joint-step law is evaluated on the
    /// actual applied E difference before a successor is returned, alongside the proposed ray.
    /// The source gain assumes participation-mean junctions, passive tick power with contrast
    /// growth and any certified Floquet reach (Lean HNN/Propagation.anchor_is_participation,
    /// HNN/Word.word_tick_balance, Holon/Deposition.active_energy_growth and entry_span_gain).
    /// The complete native-Word lift of that bound remains a #62 obligation; a finite fixture
    /// checks its own physical span rather than proving all spans. Every other FieldMaterial
    /// relation is compared before a successor is returned; E's carry remainder is never an
    /// operand of open_storage and enters only a later deposition.
    pub fn observe_source_ports(
        self,
        contemporary: &crate::hnn::constitution::Constitution,
        observed: &Encoded,
        compared: &[bool],
    ) -> Result<PhysicalTeaching, PhysicalTeachingRefusal> {
        self.observe_at(
            contemporary,
            observed,
            compared,
            PhysicalLearning::SourcePorts,
            false,
        )
    }

    /// A declared comparison changes the reached pair outputs through the same blind Word.
    /// The existing current/earlier reads, first source E, R and internal physical laws stay fixed.
    /// For each declared offset the supported relation is affine in its output rows:
    /// `delta_source_c = sum_rho delta_e_rho * a_rho^T C_c b_rho` with the actual normalized table.
    /// The general pair FactorStep supplies its carried metric, source gain and certified ray;
    /// zero directions constrain the two read factors. No output calibration is installed.
    /// The actual carried output difference must also satisfy the existing joint-step law.
    /// Rounded Words and reached quartics still refuse: their source-ray certificate is owed #62.
    pub fn observe_pair_outputs(
        self,
        contemporary: &crate::hnn::constitution::Constitution,
        observed: &Encoded,
        compared: &[bool],
    ) -> Result<PhysicalTeaching, PhysicalTeachingRefusal> {
        self.observe_at(contemporary, observed, compared, PhysicalLearning::PairOutputs, false)
    }

    fn observe_at(
        self,
        contemporary: &crate::hnn::constitution::Constitution,
        observed: &Encoded,
        compared: &[bool],
        learning: PhysicalLearning,
        read_receiving_operands: bool,
    ) -> Result<PhysicalTeaching, PhysicalTeachingRefusal> {
        use crate::hnn::constitution::{FactorGradient, LinearLocus, Locus, Reach};
        use crate::hnn::port::Deposit;
        use crate::hnn::ratio::{Faces, HolonRatio, target_phases};
        use crate::hnn::retention::Diamond;
        let Self {
            field,
            material,
            current,
            phases,
            chart,
            opening_support,
            source,
            word,
            prediction,
        } = self;
        let joined = (|| -> Result<_, HnnError> {
            if contemporary.commit() != material.commit() {
                return Err(HnnError::StaleDeposit {
                    staged: material.commit(),
                    published: contemporary.commit(),
                });
            }
            if contemporary != material {
                return Err(HnnError::Unadmitted {
                    reason: "the physical comparison's producing material changed without its commit",
                });
            }
            if observed.part(0..0)? != chart {
                return Err(HnnError::Unadmitted {
                    reason: "the observation does not share the physical source's complete producing chart",
                });
            }
            if prediction.cells.len() != phases.aperture()
                || observed.len() != phases.aperture()
                || compared.len() != phases.aperture()
            {
                return Err(HnnError::Unadmitted {
                    reason: "the observation partition is not the whole declared physical section",
                });
            }
            if !field.is_source(phases.ring()) || phases.first_epoch() != 0 {
                return Err(HnnError::Unadmitted {
                    reason: "the observation's receiving clock has no certified source station square",
                });
            }
            if !compared.iter().any(|&crossed| crossed) {
                return Err(HnnError::Unadmitted {
                    reason: "no observation crosses the declared comparison partition",
                });
            }
            let diamond = Diamond::opened(field, &phases, &opening_support);
            let full_reach = diamond.retained(field);
            if learning != PhysicalLearning::Receiving {
                if !physical_word_is_exact(word.operands()) {
                    return Err(HnnError::Unadmitted {
                        reason: if learning == PhysicalLearning::SourcePorts {
                            "source-port learning has no certificate through a rounded Word"
                        } else {
                            "pair-output learning has no certificate through a rounded Word"
                        },
                    });
                }
                if field.rings().iter().enumerate().any(|(ring, _)| {
                    full_reach.contains(&Locus::Resonator(ring))
                        && material
                            .ring_resonator(ring)
                            .is_some_and(|law| law.saturation().is_some())
                }) {
                    return Err(HnnError::Unadmitted {
                        reason: if learning == PhysicalLearning::SourcePorts {
                            "source-port learning through a reached quartic needs the Word-Hessian certificate"
                        } else {
                            "pair-output learning through a reached quartic needs the Word-Hessian certificate"
                        },
                    });
                }
            }
            let reads: Vec<_> = prediction
                .reads
                .iter()
                .map(|station| station.read.clone())
                .collect();
            let targets: Vec<_> = observed.classes_read().collect();
            let ratio = HolonRatio::compare_partition(
                Faces::of_reads(&reads, phases.grain())?,
                &targets,
                &target_phases(field, current.lift(), phases.ring(), observed)?,
                compared,
            )?;
            let map =
                material
                    .receiving_map(phases.ring())
                    .ok_or(HnnError::MissingReceivingMap {
                        ring: phases.ring(),
                    })?;
            // Preserve only the producing operands/absolute opening until the immediate source
            // publication check. The Word itself is consumed once by its existing paired return.
            let source_return = (learning != PhysicalLearning::Receiving)
                .then(|| (word.operands().clone(), word.opened_at()));
            let covector = ratio.covector()?;
            let back = word.pull_back(
                &covector,
                map,
                &current.lift()[phases.ring()],
                &phases,
            )?;
            let composed = crate::hnn::reference::compose_return(
                field,
                material,
                &diamond,
                current.lift(),
                &current,
                &source,
                &back,
            )?;
            let mut factors = Vec::new();
            if learning == PhysicalLearning::PairOutputs {
                for mut step in composed.factors {
                    if let FactorGradient::PairPort { outputs, current, earlier, .. } = &mut step.gradient {
                        if step.energy.is_zero() || outputs.iter().flatten().all(Zero::is_zero) {
                            continue;
                        }
                        // The chosen general subfamily changes output rows only. A comparison-free
                        // read-factor direction contributes neither a move nor a fabricated gradient.
                        for value in current.iter_mut().chain(earlier.iter_mut()).flatten() {
                            *value = Rat::zero();
                        }
                        factors.push(step);
                    }
                }
            }
            let mut linear: Vec<_> = composed
                .linear
                .into_iter()
                .filter(|step| match learning {
                    PhysicalLearning::Receiving => {
                        step.locus == LinearLocus::Receiving(phases.ring())
                    }
                    PhysicalLearning::SourcePorts => {
                        matches!(step.locus, LinearLocus::SourcePort(_))
                    }
                    PhysicalLearning::PairOutputs => false,
                })
                .collect();
            match learning {
                PhysicalLearning::Receiving => {
                    // R's samples are one per station. An unobserved station leaves no normal
                    // statistic; the feature is its existing rotated receiving anchor.
                    for step in &mut linear {
                        if step.samples.len() != compared.len() {
                            return Err(HnnError::Shape {
                                what: "the reached receiving samples against the observation partition",
                                expected: compared.len(),
                                found: step.samples.len(),
                            });
                        }
                        step.samples = std::mem::take(&mut step.samples)
                            .into_iter()
                            .zip(compared)
                            .filter_map(|(sample, &crossed)| crossed.then_some(sample))
                            .collect();
                    }
                }
                PhysicalLearning::SourcePorts => {
                    // E's samples are occupied source phases, already pulled back from the
                    // masked comparison. Input alone must not retain a Gram/chart statistic.
                    for step in &mut linear {
                        step.samples.retain(|sample| {
                            !sample.weight.is_zero()
                                && sample.feature.iter().any(|value| !value.is_zero())
                                && sample.covector.iter().any(|value| !value.is_zero())
                        });
                    }
                    linear.retain(|step| !step.samples.is_empty());
                }
                PhysicalLearning::PairOutputs => {}
            }
            let reached: Vec<_> = linear.iter().map(|step| step.locus.locus())
                .chain(factors.iter().map(|step| step.gradient.locus()))
                .collect::<std::collections::BTreeSet<_>>().into_iter().collect();
            if reached.is_empty()
                || reached
                    .iter()
                    .any(|locus| !composed.reached.contains(locus))
            {
                return Err(HnnError::Unadmitted {
                    reason: "the physical comparison reaches no nonzero sample at the selected relation",
                });
            }
            let reach = Reach {
                receiver: phases.ring(),
                stations: phases
                    .epochs()
                    .zip(compared)
                    .filter_map(|(tick, &crossed)| crossed.then_some(tick as u64))
                    .collect(),
                entries: vec![0],
                phases: composed.phases,
                loci: match learning {
                    PhysicalLearning::Receiving => reached.iter().copied().collect(),
                    PhysicalLearning::SourcePorts | PhysicalLearning::PairOutputs => full_reach,
                },
            };
            let deposit =
                Deposit::new(material.commit(), linear, factors, reached).with_reach(reach);
            let feature_energy = deposit.linear().iter().map(|step| {
                (step.locus.locus(), step.samples.iter().map(|sample| {
                    &sample.weight * sample.feature.iter().map(|value| value*value).sum::<Rat>()
                }).sum::<Rat>())
            }).chain(deposit.factors().iter().map(|step| {
                (step.gradient.locus(), step.energy.clone())
            })).collect();
            let (constitution, publication) = contemporary.deposited(&deposit)?;
            // Read only already executed operands. The normal-law snapshots and samples are
            // returned to the exterior caller; none is installed in the contemporary successor.
            let receiving_diagnostic = (read_receiving_operands && learning == PhysicalLearning::Receiving)
                .then(|| {
                    material.receiving_law(phases.ring())
                        .zip(constitution.receiving_law(phases.ring()))
                        .and_then(|(before, after)| {
                            deposit.linear().iter()
                                .find(|step| step.locus == LinearLocus::Receiving(phases.ring()))
                                .map(|step| PhysicalReceivingDiagnostic {
                                    producing_commit: material.commit(),
                                    receiver: phases.ring(),
                                    source_lift: current.lift().to_vec(),
                                    crossings: prediction.reads.iter().zip(compared)
                                        .filter_map(|(read, &crossed)| crossed.then_some(
                                            PhysicalReceivingCrossing {
                                                station: read.station,
                                                crossing: read.crossing,
                                                tick: read.tick,
                                            }))
                                        .collect(),
                                    samples: step.samples.clone(),
                                    before: before.clone(),
                                    after: after.clone(),
                                })
                        })
                })
                .flatten();
            let source_certificate = if learning == PhysicalLearning::SourcePorts {
                if !physical_source_only_change(field, material, &constitution, &publication.loci, &[])
                    || material.released() != constitution.released()
                    || material.storage_product() != constitution.storage_product()
                {
                    return Err(HnnError::Unadmitted {
                        reason: "the proposed physical E successor changes another forward relation",
                    });
                }
                // The budgeted map carry need not equal eta*D: old/new remainders and releases
                // complete that accounting. Certify the *applied* E move with the existing joint
                // law, using its actual alignment and feature moves, before returning a successor.
                let mut sources = Vec::new();
                for step in deposit.linear() {
                    let LinearLocus::SourcePort(ring) = step.locus else {
                        unreachable!()
                    };
                    let delta = constitution
                        .source_port(ring)
                        .ok_or(HnnError::MissingSourcePort { ring })?
                        .subtract(
                            material
                                .source_port(ring)
                                .ok_or(HnnError::MissingSourcePort { ring })?,
                        )?;
                    let (mut moved, mut alignment) = (Rat::zero(), Rat::zero());
                    for sample in &step.samples {
                        let output = delta.apply(&sample.feature)?;
                        moved += &sample.weight * output.iter().map(|x| x * x).sum::<Rat>();
                        alignment += &sample.weight
                            * sample
                                .covector
                                .iter()
                                .zip(&output)
                                .map(|(g, x)| g * x)
                                .sum::<Rat>();
                    }
                    let reading = publication.steps.iter()
                        .find(|(at, reading)| *at == Locus::SourcePort(ring)
                            && reading.family == crate::hnn::constitution::Family::Map)
                        .ok_or(HnnError::Unadmitted {
                            reason: "the physical E successor has no source feature-move certificate",
                        })?;
                    let gain = reading.1.gain.clone();
                    let bound = crate::holon::deposition::root_ceiling(&(&gain * &moved));
                    sources.push(PhysicalSourceMove {
                        ring,
                        alignment,
                        moves: moved,
                        gain,
                        bound,
                    });
                }
                let one = Rat::one();
                let joint = crate::holon::deposition::JointReading::read(
                    &crate::ratio::rat(1, 2),
                    sources
                        .iter()
                        .map(|source| (&one, &source.alignment, &source.bound)),
                );
                if !joint.holds() {
                    return Err(HnnError::Unadmitted {
                        reason: "the actual carried source move fails its physical joint-step certificate",
                    });
                }
                Some(PhysicalSourceCertificate { sources, joint })
            } else if learning == PhysicalLearning::PairOutputs {
                let selected: Vec<_> = deposit.factors().iter().filter_map(|step| {
                    match &step.gradient {
                        FactorGradient::PairPort { ring, offset, .. } => Some((*ring, *offset)),
                        _ => None,
                    }
                }).collect();
                if !physical_source_only_change(field, material, &constitution, &[], &selected)
                    || material.released() != constitution.released()
                    || material.storage_product() != constitution.storage_product()
                {
                    return Err(HnnError::Unadmitted {
                        reason: "the physical pair-output successor changes another forward relation",
                    });
                }
                Some(physical_pair_output_certificate(field, material, &constitution,
                    &source, deposit.factors(), &publication)?)
            } else {
                None
            };
            let source_pairing = match (source_return, &source_certificate) {
                (Some((operands, opened_at)), Some(applied)) => Some(physical_source_pairing(
                    field, material, &constitution, &current, &phases, &source, &operands,
                    opened_at, &prediction, &covector, &back, compared, applied,
                )?),
                (None, None) => None,
                _ => return Err(HnnError::Unadmitted {
                    reason: "the source publication has no producing Word for its applied pairing",
                }),
            };
            Ok((
                ratio,
                composed.pullback,
                constitution,
                publication,
                source_certificate,
                source_pairing,
                feature_energy,
                receiving_diagnostic,
            ))
        })();
        match joined {
            Ok((ratio, pullback, constitution, publication, source_certificate, source_pairing, feature_energy, receiving_diagnostic)) => {
                Ok(PhysicalTeaching {
                    prediction,
                    ratio,
                    pullback,
                    constitution,
                    publication,
                    source_certificate,
                    source_pairing,
                    feature_energy,
                    receiving_diagnostic,
                })
            }
            Err(error) => Err(PhysicalTeachingRefusal { prediction, error }),
        }
    }
}

/// [definition; agent-inferred, October 5] **The classes an erased station's domain projects
/// to** when the finite tube cannot be admitted: the full encoding fibre. A component domain under
/// a frozen drive, a local tangent and a point leader do not certify the coupled Word.
/// (`PeriodicLock::phase_class` is a pump phase index, not a class.)
fn domain_classes(section: &DamagedSection) -> Vec<usize> {
    (0..section.classes()).collect()
}

/// **The one decision on an erased station**: its class reading over the domain has width zero
/// exactly when the domain projects to one class, decided by `receiver::release` at tolerance
/// zero: released, or held with the projected classes as its fibre.
fn decide_station(
    station: usize,
    admitted: &[usize],
    unresolved: Unresolved,
) -> Result<RepairedCell, HnnError> {
    let rule = DecisionRule::new(
        "the physical repair's commit at tolerance zero",
        WithinTolerance::Release,
        BeyondTolerance::Hold,
    );
    let (diameter, attaining, read) = if admitted.len() == 1 {
        (Rat::zero(), WidthWitness::Point, 1)
    } else {
        (
            Rat::one(),
            WidthWitness::Pair { left: 0, right: 1 },
            admitted.len().max(2),
        )
    };
    let width = ReceiverWidth::declared(
        format!("the physically repaired station {station}"),
        "the station's class over the projection of its word's domain through the decoder",
        DiameterNorm::Supremum,
        diameter,
        attaining,
        read,
    )?;
    let options = LawfulOptions::assemble(&width, Rat::zero(), None, true)?;
    Ok(match release(&rule, &options)? {
        ReleaseReturn::Released { .. } => RepairedCell::Released(admitted[0]),
        _ => RepairedCell::Held {
            fibre: admitted.to_vec(),
            unresolved,
        },
    })
}
